registerClass12ExerciseBanks("chem", {"14":{"items":{"mcqs":[{"q":[["chem12-u14-exercise",2]],"s":["Cu⁺ is [Ar]3d¹⁰: all electrons are paired.","Ni²⁺ (3d⁸), Cr³⁺ (3d³) and Mn²⁺ (3d⁵) have unpaired electrons and are paramagnetic. So Cu⁺ is diamagnetic."],"o":[["chem12-u14-exercise",3],["chem12-u14-exercise",4],["chem12-u14-exercise",5],["chem12-u14-exercise",6]],"c":3},{"q":[["chem12-u14-exercise",7]],"s":["Potassium ferrocyanide K₄[Fe(CN)₆] contains the complex ion [Fe(CN)₆]⁴⁻, which keeps its identity in solution.","It is a complex salt."],"o":[["chem12-u14-exercise",8],["chem12-u14-exercise",9],["chem12-u14-exercise",10],["chem12-u14-exercise",11]],"c":3},{"q":[["chem12-u14-exercise",12]],"s":["Cu²⁺ with four chloride ligands forms [CuCl₄]²⁻, which is (distorted) tetrahedral."],"o":[["chem12-u14-exercise",13],["chem12-u14-exercise",14],["chem12-u14-exercise",15],["chem12-u14-exercise",16]],"c":0},{"q":[["chem12-u14-exercise",17]],"s":["Let the oxidation state of Cr be x: x + 2(−2) + 2(−1) = 0.","x = +6."],"o":[["chem12-u14-exercise",18],["chem12-u14-exercise",19],["chem12-u14-exercise",20],["chem12-u14-exercise",21]],"c":3},{"q":[["chem12-u14-exercise",22]],"s":["Be²⁺ has no d orbitals; it uses sp³ hybrid orbitals for four F⁻ ligands.","[BeF₄]²⁻ is a tetrahedral complex."],"o":[["chem12-u14-exercise",23],["chem12-u14-exercise",24],["chem12-u14-exercise",25],["chem12-u14-exercise",26]],"c":1},{"q":[["chem12-u14-exercise",27]],"s":["A typical transition element has an incompletely filled d subshell in the atom or a common ion.","Zn and Cd have completely filled d¹⁰ subshells and Ra is an s-block element; cobalt (3d⁷4s²) is a typical transition element."],"o":[["chem12-u14-exercise",28],["chem12-u14-exercise",29],["chem12-u14-exercise",30],["chem12-u14-exercise",31]],"c":3},{"q":[["chem12-u14-exercise",32]],"s":["Paramagnetism arises from unpaired electrons, each with an uncompensated spin magnetic moment.","It depends on the number of unpaired electrons."],"o":[["chem12-u14-exercise",33],["chem12-u14-exercise",34],["chem12-u14-exercise",35],["chem12-u14-exercise",36]],"c":2},{"q":[["chem12-u14-exercise",37]],"s":["Ligands donate a lone pair of electrons to the central metal ion to form coordinate bonds.","They are electron-pair donors (Lewis bases)."],"o":[["chem12-u14-exercise",38],["chem12-u14-exercise",39],["chem12-u14-exercise",40],["chem12-u14-exercise",41]],"c":0},{"q":[["chem12-u14-exercise",42]],"s":["Fe, Co and Ni are the ferromagnetic metals.","Antimony (Sb) is not ferromagnetic."],"o":[["chem12-u14-exercise",43],["chem12-u14-exercise",44],["chem12-u14-exercise",45],["chem12-u14-exercise",46]],"c":2},{"q":[["chem12-u14-exercise",47]],"s":["Six CN⁻ ligands are each bonded to Fe through one donor atom.","Coordination number = 6."],"o":[["chem12-u14-exercise",48],["chem12-u14-exercise",49],["chem12-u14-exercise",50],["chem12-u14-exercise",51]],"c":3},{"q":[["chem12-u14-exercise",52]],"s":["A bidentate ligand bonds through two donor atoms.","Oxalate C₂O₄²⁻ binds through two oxygen atoms; H₂O, NH₃ and CO are monodentate."],"o":[["chem12-u14-exercise",53],["chem12-u14-exercise",54],["chem12-u14-exercise",55],["chem12-u14-exercise",56]],"c":3},{"q":[["chem12-u14-exercise",57]],"s":["In [Cu(H₂O)₆]²⁺ the ligands split the 3d orbitals.","Absorption of red-orange light promotes an electron from a lower to a higher d orbital (d–d transition), so the solution looks blue."],"o":[["chem12-u14-exercise",58],["chem12-u14-exercise",59],["chem12-u14-exercise",60],["chem12-u14-exercise",61]],"c":1},{"q":[["chem12-u14-exercise",62]],"s":["In acid solution Cr₂O₇²⁻ + 14H⁺ + 6e⁻ → 2Cr³⁺ + 7H₂O.","It accepts electrons easily, so potassium dichromate is a strong oxidising agent."],"o":[["chem12-u14-exercise",63],["chem12-u14-exercise",64],["chem12-u14-exercise",65],["chem12-u14-exercise",66]],"c":0},{"q":[["chem12-u14-exercise",67]],"s":["German silver is an alloy of copper, zinc and nickel (it contains no silver).","Cu is a constituent."],"o":[["chem12-u14-exercise",68],["chem12-u14-exercise",69],["chem12-u14-exercise",70],["chem12-u14-exercise",71]],"c":2},{"q":[["chem12-u14-exercise",72]],"s":["In naming coordination compounds, anionic ligands end in -o (chlorido, cyanido), but neutral ligands keep their names (e.g. ethylenediamine).","Common exceptions are aqua (H₂O), ammine (NH₃), carbonyl (CO) and nitrosyl (NO)."],"o":[["chem12-u14-exercise",73],["chem12-u14-exercise",74],["chem12-u14-exercise",75],["chem12-u14-exercise",76]],"c":2}],"shortQuestions":[{"q":[["chem12-u14-exercise",78]],"s":["Cu⁺: [Ar]3d¹⁰ — all ten d electrons are paired, so there is no net magnetic moment and it is diamagnetic.","Cu²⁺: [Ar]3d⁹ — one unpaired electron gives a magnetic moment, so it is paramagnetic."]},{"q":[["chem12-u14-exercise",79]],"s":["Sc [Ar]3d¹4s², Ti [Ar]3d²4s², V [Ar]3d³4s², Cr [Ar]3d⁵4s¹, Mn [Ar]3d⁵4s².","Fe [Ar]3d⁶4s², Co [Ar]3d⁷4s², Ni [Ar]3d⁸4s², Cu [Ar]3d¹⁰4s¹, Zn [Ar]3d¹⁰4s²."]},{"q":[["chem12-u14-exercise",80]],"s":["Transition metals show variable oxidation states, so they can form unstable intermediate compounds and then regenerate (e.g. Fe²⁺/Fe³⁺).","They have vacant d orbitals and large surface areas, so reactant molecules are adsorbed and their bonds weakened.","Both provide an alternative reaction path of lower activation energy, so they act as catalysts."]},{"q":[["chem12-u14-exercise",81]],"s":["Transition metal ions are small and highly charged (high charge density), so they strongly attract ligands.","They have vacant (n−1)d, ns and np orbitals of suitable energy that can accept lone pairs from ligands, forming coordinate bonds and complex ions."]},{"q":[["chem12-u14-exercise",82]],"s":["The (n−1)d and ns orbitals have very similar energies.","So electrons from both the 4s and the 3d subshells can be lost or shared in different numbers, giving several oxidation states (e.g. Mn shows +2 to +7)."]},{"q":[["chem12-u14-exercise",83]],"s":["Scandium forms compounds only in the +3 state; Sc³⁺ has the configuration [Ar] with no 3d electrons.","With no d electrons there can be no d–d transitions, so its compounds absorb no visible light and are colourless; with no unpaired electrons they are diamagnetic."]},{"q":[["chem12-u14-exercise",84]],"s":["Transition elements have partly filled d subshells; s- and p-block elements do not.","Transition elements show variable oxidation states, form coloured and paramagnetic compounds, form many complexes, act as catalysts and are hard, dense metals with high melting points and alloys.","s-block elements show fixed oxidation states (+1, +2) and mostly colourless, diamagnetic compounds; p-block elements include non-metals and form mainly covalent compounds."]},{"q":[["chem12-u14-exercise",85]],"s":["H₂O is a neutral ligand, so the charge of the complex equals the charge of Cr.","x + 6(0) = +3, so chromium is in the +3 oxidation state."]},{"q":[["chem12-u14-exercise",86]],"s":["In the Haber process (N₂ + 3H₂ ⇌ 2NH₃) iron adsorbs N₂ and H₂ on its surface and weakens their bonds — a reducing environment in which iron stays metallic.","In the contact process the catalyst must transfer oxygen to SO₂ by changing oxidation state reversibly (V₂O₅ ⇌ V₂O₄). In the oxidising, acidic SO₂/SO₃ atmosphere iron would be oxidised and converted into iron sulphate (catalyst poisoned), so V₂O₅ (or Pt) is used instead."]},{"q":[["chem12-u14-exercise",87]],"s":["Zn²⁺ is 3d¹⁰: the d subshell is full, so no d–d transition is possible; no visible light is absorbed and its salts are white.","Cu²⁺ is 3d⁹: an electron can be promoted between split d orbitals by absorbing visible (red-orange) light, so its salts are coloured (blue)."]}],"longQuestions":[{"q":[["chem12-u14-exercise",89],["chem12-u14-exercise",90]],"s":["(a) Electronic structures of 3d elements: Sc [Ar]3d¹4s², Ti 3d²4s², V 3d³4s², Cr 3d⁵4s¹, Mn 3d⁵4s², Fe 3d⁶4s², Co 3d⁷4s², Ni 3d⁸4s², Cu 3d¹⁰4s¹, Zn 3d¹⁰4s².","(b) By the Aufbau principle chromium would be 3d⁴4s² and copper 3d⁹4s². Instead Cr is 3d⁵4s¹ and Cu is 3d¹⁰4s¹.","The 3d and 4s energies are very close, and a half-filled (d⁵) or completely filled (d¹⁰) subshell has extra stability (symmetrical distribution and greater exchange energy).","So one 4s electron moves into the 3d subshell, giving the more stable half-filled or filled arrangement."]},{"q":[["chem12-u14-exercise",91],["chem12-u14-exercise",92],["chem12-u14-exercise",93]],"s":["(a) Origin of colour: in a complex the ligands split the five d orbitals into two sets of different energy (crystal-field splitting Δ). An electron in a lower d orbital absorbs a photon of visible light whose energy equals Δ and jumps to a higher d orbital (d–d transition). The complementary colour of the absorbed light is seen, e.g. [Cu(H₂O)₆]²⁺ absorbs orange-red and looks blue. The colour depends on the metal, its oxidation state and the ligands. Ions with d⁰ or d¹⁰ are colourless.","(b) General characteristics of transition elements: metals with high melting and boiling points, hardness and density; variable oxidation states; coloured ions; paramagnetism; formation of complexes; catalytic activity; formation of interstitial compounds and alloys.","(c) Vanadium: V₂O₅ catalyses the contact process, 2SO₂ + O₂ → 2SO₃, by changing oxidation state: V₂O₅ + SO₂ → V₂O₄ + SO₃, then V₂O₄ + ½O₂ → V₂O₅. Iron: finely divided iron (promoted with K₂O and Al₂O₃) catalyses the Haber process N₂ + 3H₂ ⇌ 2NH₃ by adsorbing the gases on its surface; Fe²⁺/Fe³⁺ ions also catalyse the reaction between I⁻ and S₂O₈²⁻ by switching oxidation state."]},{"q":[["chem12-u14-exercise",94]],"s":["IUPAC rules: (1) Name the cation first, then the anion. (2) Within the complex, name the ligands first in alphabetical order, then the metal. (3) Number of ligands: di-, tri-, tetra-, penta-, hexa- (bis-, tris- for complicated ligands).","(4) Anionic ligands end in -o: chlorido (Cl⁻), cyanido (CN⁻), hydroxido (OH⁻), oxalato (C₂O₄²⁻). Neutral ligands keep their names, except aqua (H₂O), ammine (NH₃), carbonyl (CO), nitrosyl (NO).","(5) The oxidation state of the metal is given in Roman numerals in brackets. (6) If the complex is an anion, the metal name ends in -ate (ferrate, cuprate, argentate, aurate).","Examples: [Cu(NH₃)₄]SO₄ — tetraamminecopper(II) sulphate; K₄[Fe(CN)₆] — potassium hexacyanidoferrate(II); [Co(NH₃)₅Cl]Cl₂ — pentaamminechloridocobalt(III) chloride; [Ni(CO)₄] — tetracarbonylnickel(0); K₂[PtCl₆] — potassium hexachloridoplatinate(IV)."]},{"q":[["chem12-u14-exercise",95],["chem12-u14-exercise",96]],"s":["(a) Potassium manganate(VII), KMnO₄, is a strong oxidising agent. Cold, dilute alkaline KMnO₄ oxidises alkenes to diols (Baeyer's test — the purple colour disappears and brown MnO₂ forms): CH₂=CH₂ + H₂O + [O] → HOCH₂–CH₂OH.","Hot acidified KMnO₄ cleaves alkenes (e.g. to carboxylic acids or ketones), oxidises primary alcohols to carboxylic acids (RCH₂OH + 2[O] → RCOOH + H₂O), aldehydes to acids, and side chains of benzene rings to benzoic acid: C₆H₅CH₃ + 3[O] → C₆H₅COOH + H₂O. In acid, MnO₄⁻ + 8H⁺ + 5e⁻ → Mn²⁺ + 4H₂O.","(b) An alloy is a homogeneous mixture of two or more metals (or a metal with a non-metal), e.g. brass (Cu + Zn), bronze (Cu + Sn), steel (Fe + C), German silver (Cu + Zn + Ni), stainless steel (Fe + Cr + Ni).","Properties different from the component metals: alloys are usually harder and stronger (different-sized atoms stop the layers sliding), have lower melting points, better resistance to corrosion, and lower electrical and thermal conductivity; their colour may differ."]},{"q":[["14.18",0],["14.18",1]],"s":["(a) Copper shows +1 and +2 oxidation states. Cu⁺ (3d¹⁰) occurs in insoluble or solid compounds such as Cu₂O and CuCl; in water Cu⁺ disproportionates: 2Cu⁺ → Cu + Cu²⁺. Cu²⁺ (3d⁹) is the most common and stable state in aqueous solution, forming blue [Cu(H₂O)₆]²⁺ (CuSO₄, CuCl₂, Cu(NO₃)₂).","(b) With hydroxide ions: [Cu(H₂O)₆]²⁺ + 2OH⁻ → [Cu(H₂O)₄(OH)₂] + 2H₂O, a pale blue precipitate.","With ammonia: a little ammonia gives the same pale blue precipitate; with excess ammonia it dissolves to a deep blue solution: [Cu(H₂O)₆]²⁺ + 4NH₃ → [Cu(NH₃)₄(H₂O)₂]²⁺ + 4H₂O.","With carbonate ions: [Cu(H₂O)₆]²⁺ + CO₃²⁻ → CuCO₃ + 6H₂O, a blue-green precipitate (basic copper carbonate)."]}],"activities":[{"q":[["14.18",3]],"s":["Observations: on heating, the deep blue crystals of CuSO₄·5H₂O gradually turn pale and finally become a white powder; water vapour is given off and may condense on the cooler parts of the container.","Equation: CuSO₄·5H₂O(s) → CuSO₄(s) + 5H₂O(g)."]},{"q":[["14.18",4]],"s":["After heating, the blue colour disappears and white anhydrous copper(II) sulphate remains, because the water of crystallisation has been driven off."]},{"q":[["14.18",5]],"s":["The blue colour comes from Cu²⁺ ions surrounded by water molecules acting as ligands. These ligands split the 3d orbitals so that red-orange light is absorbed in d–d transitions.","When the water is removed, this ligand arrangement is lost; the anhydrous salt absorbs no visible light, so the colour disappears."]},{"q":[["14.18",6]],"s":["The colour change is caused by the loss of water ligands: in CuSO₄·5H₂O, [Cu(H₂O)₄]²⁺ units have a crystal-field splitting that matches visible light.","In anhydrous CuSO₄ the Cu²⁺ ion is surrounded by sulphate oxygens, which give a different splitting whose absorption lies outside the visible region, so the solid looks white."]},{"q":[["14.18",7]],"s":["On adding water, the white powder turns blue again and becomes warm (the reaction is exothermic).","CuSO₄(s) + 5H₂O(l) → CuSO₄·5H₂O(s). This is used as a test for water."]},{"q":[["14.18",8]],"s":["Water molecules again coordinate to the Cu²⁺ ions as ligands, restoring the d-orbital splitting.","The d–d transitions absorb red-orange light once more, so the deep blue colour reappears."]}]}},"15":{"items":{"mcqs":[{"q":[["15.7",13]],"s":["In 1828 Friedrich Wöhler heated ammonium cyanate (an inorganic salt) and obtained urea.","Urea was the first organic compound prepared in the laboratory; this disproved the vital force theory."],"o":[["15.7",14],["15.7",15],["15.7",16],["15.7",17]],"c":1},{"q":[["15.7",18]],"s":["Urea, methane and acetic acid are carbon compounds studied in organic chemistry.","Graphite is an elemental allotrope of carbon, not an organic compound."],"o":[["15.7",19],["15.7",20],["15.7",21],["15.7",22]],"c":0},{"q":[["15.7",23]],"s":["Carbon content: peat ≈ 60%, lignite ≈ 70%, bituminous ≈ 80%, anthracite ≈ 90%.","Anthracite has the highest percentage of carbon."],"o":[["15.7",24],["15.7",25],["15.7",26],["15.7",27]],"c":0},{"q":[["15.7",28]],"s":["Crude petroleum is mainly a mixture of saturated hydrocarbons (alkanes and cycloalkanes), with smaller amounts of aromatic hydrocarbons."],"o":[["15.7",29],["15.7",30],["15.7",31],["15.7",32]],"c":2},{"q":[["15.7",33]],"s":["Natural gas is mostly methane (about 85–95%), with small amounts of ethane, propane and butane."],"o":[["15.7",34],["15.7",35],["15.7",36],["15.7",37]],"c":3},{"q":[["15.7",38]],"s":["Destructive distillation of coal gives coal gas, ammoniacal liquor, coal tar and coke.","Refinery gas is a fraction of petroleum (fractional distillation of crude oil), not of coal."],"o":[["15.7",39],["15.7",40],["15.7",41],["15.7",42]],"c":1},{"q":[["15.7",43]],"s":["In the Fischer–Tropsch process coal is first turned into water gas (CO + H₂), which is then combined over a catalyst to give alkanes (synthetic petrol)."],"o":[["15.7",44],["15.7",45],["15.7",46],["15.7",47]],"c":2},{"q":[["15.7",48]],"s":["Pyridine C₅H₅N has a six-membered ring containing a nitrogen atom.","A ring containing an atom other than carbon is heterocyclic."],"o":[["15.7",49],["15.7",50],["15.7",51],["15.7",52]],"c":0},{"q":[["15.7",53]],"s":["Amides contain the –CONH₂ group (e.g. CH₃CONH₂).","–COOR is an ester, –NH₂ an amine and –C≡N a nitrile."],"o":[["15.7",54],["15.7",55],["15.7",56],["15.7",57]],"c":3},{"q":[["15.7",58]],"s":["Cl, P and N can be detected by tests (e.g. Lassaigne's test).","There is no direct test for oxygen; it is found by difference after estimating the other elements."],"o":[["15.7",59],["15.7",60],["15.7",61],["15.7",62]],"c":3},{"q":[["15.7",63]],"s":["Sodium fusion converts N, S and halogens into NaCN, Na₂S and NaX.","The Lassaigne's extract is tested for nitrogen, sulphur and halogens — all of these."],"o":[["15.7",64],["15.7",65],["15.7",66],["15.7",67]],"c":3},{"q":[["15.7",68]],"s":["Silver nitrate gives AgCl (white, soluble in NH₄OH), AgBr (pale yellow, sparingly soluble) and AgI (yellow, insoluble).","A yellow precipitate insoluble in ammonium hydroxide shows iodine."],"o":[["15.7",69],["15.7",70],["15.7",71],["15.7",72]],"c":2},{"q":[["15.7",73]],"s":["Fischer–Tropsch: nCO + (2n + 1)H₂ → CₙH₂ₙ₊₂ + nH₂O over Fe/Co catalyst.","Alkanes are formed from CO and H₂."],"o":[["15.7",74],["15.7",75],["15.7",76],["15.7",77]],"c":0},{"q":[["15.7",78]],"s":["Buckminsterfullerene C₆₀ is a cage of 12 pentagonal and 20 hexagonal carbon rings, like a football.","So it contains both pentagonal and hexagonal rings."],"o":[["15.7",79],["15.7",80],["15.7",81],["15.7",82]],"c":3},{"q":[["15.8",0]],"s":["Pyridine has nitrogen in its ring, so it contains nitrogen and is a heterocyclic compound.","Both b and c are correct."],"o":[["15.8",1],["15.8",2],["15.8",3],["15.8",4]],"c":3}],"shortQuestions":[{"q":[["15.8",6]],"s":["Organic compounds are the compounds of carbon (chiefly with hydrogen, and also with O, N, S, P and halogens), i.e. hydrocarbons and their derivatives — excluding simple carbon compounds such as oxides of carbon, carbonates and cyanides.","Organic chemistry is the branch of chemistry that deals with the study of hydrocarbons and their derivatives."]},{"q":[["15.8",7]],"s":["Lassaigne's test: fuse a small piece of sodium with the organic compound in an ignition tube; plunge the red-hot tube into distilled water, boil and filter. The filtrate is the sodium (Lassaigne's) extract. Na + C + N → NaCN.","Boil part of the extract with freshly prepared FeSO₄ solution, cool, add a few drops of FeCl₃ and acidify with dilute H₂SO₄.","A Prussian blue colour or precipitate shows nitrogen: 6NaCN + FeSO₄ → Na₄[Fe(CN)₆] + Na₂SO₄; 3Na₄[Fe(CN)₆] + 4FeCl₃ → Fe₄[Fe(CN)₆]₃ (Prussian blue) + 12NaCl."]},{"q":[["15.8",8]],"s":["A homologous series is a group of organic compounds with the same functional group in which each member differs from the next by a –CH₂– group.","Characteristics: all members have the same general formula (e.g. alkanes CₙH₂ₙ₊₂); they have similar chemical properties; their physical properties (boiling point, density) change gradually with molecular mass; they can be prepared by similar general methods; successive molecular masses differ by 14."]},{"q":[["15.8",9]],"s":["Buckminsterfullerene (C₆₀) is an allotrope of carbon, but its molecule is a closed cage of fused five- and six-membered carbon rings with alternating double bonds, rather like aromatic compounds.","It behaves like an organic molecule: it dissolves in organic solvents and undergoes organic reactions (addition, hydrogenation, halogenation) forming many derivatives. So it is studied in organic chemistry."]},{"q":[["15.8",10]],"s":["Carbon monoxide (CO) and carbon dioxide (CO₂).","Carbonates and hydrogencarbonates (CaCO₃, NaHCO₃), carbides (CaC₂, SiC), cyanides and cyanates (KCN, KCNO), hydrogen cyanide, carbonic acid and metal carbonyls. These are studied in inorganic chemistry."]},{"q":[["15.8",11]],"s":["Partial synthesis: preparing a compound starting from a naturally occurring compound that already has much of the required structure, e.g. semi-synthetic penicillins made from natural penicillin, or vitamin preparations from natural steroids.","Total synthesis: preparing a compound entirely from simple starting materials (ultimately from the elements), e.g. Wöhler's synthesis of urea and Kolbe's synthesis of acetic acid."]},{"q":[["15.8",12]],"s":["Fischer–Tropsch process: coal (coke) is heated with steam to give water gas, C + H₂O → CO + H₂.","Water gas, enriched with hydrogen, is passed over an iron or cobalt catalyst at about 200–300 °C and a few atmospheres: nCO + (2n + 1)H₂ → CₙH₂ₙ₊₂ + nH₂O, giving a mixture of hydrocarbons (synthetic petrol).","(Bergius process: powdered coal is hydrogenated directly with H₂ at high pressure over a catalyst.)"]},{"q":[["15.8",13]],"s":["Catenation: carbon atoms link with one another to form long chains, branched chains and rings of almost any size.","Tetravalency: each carbon forms four strong covalent bonds, including double and triple bonds.","Carbon bonds strongly with H, O, N, S, P and halogens.","Isomerism: the same molecular formula can give many different structures. Together these give millions of organic compounds."]},{"q":[["15.8",14]],"s":["Acyclic (open-chain or aliphatic) compounds have carbon atoms joined in straight or branched chains with no ring, e.g. butane CH₃CH₂CH₂CH₃, isobutane.","Cyclic (closed-chain) compounds have atoms joined in rings: homocyclic rings contain only carbon (alicyclic, e.g. cyclohexane; aromatic, e.g. benzene) and heterocyclic rings contain another atom (e.g. pyridine, furan)."]}],"longQuestions":[{"q":[["15.8",16]],"s":["Fossil fuels are fuels formed from the remains of plants and animals buried for millions of years under high temperature and pressure without air. They are coal, petroleum and natural gas.","Coal: a black solid formed from plant remains; types (rank) by increasing carbon content — peat (≈ 60%), lignite (≈ 70%), bituminous (≈ 80%) and anthracite (≈ 90%). Used as fuel and, by destructive distillation, as a source of coke, coal gas and coal tar.","Petroleum (crude oil): a dark viscous liquid mixture of mainly saturated hydrocarbons, found trapped in porous rocks. It is refined by fractional distillation into refinery gas, petrol, naphtha, kerosene, diesel, lubricating oils, paraffin wax and bitumen.","Natural gas: mainly methane (with ethane, propane, butane), found above petroleum deposits or alone; a clean fuel for homes, industry and vehicles (CNG) and a raw material for fertilisers.","Fossil fuels are non-renewable, and their burning releases CO₂ and pollutants."]},{"q":[["15.8",17]],"s":["Carbon and hydrogen: heat the compound with dry copper(II) oxide. Carbon is oxidised to CO₂, which turns lime water milky; hydrogen forms H₂O, which turns white anhydrous CuSO₄ blue.","Nitrogen, sulphur and halogens — Lassaigne's test: fuse with sodium to convert them into NaCN, Na₂S and NaX, then dissolve in water (sodium extract).","Nitrogen: boil with FeSO₄, add FeCl₃ and acidify — Prussian blue colour. Sulphur: add sodium nitroprusside — violet colour; or add lead acetate and acetic acid — black precipitate of PbS. Nitrogen and sulphur together give NaSCN, which gives a blood-red colour with FeCl₃.","Halogens: acidify with dilute HNO₃, boil off HCN and H₂S, add AgNO₃ — white AgCl (soluble in NH₄OH) shows chlorine, pale yellow AgBr (sparingly soluble) bromine, yellow AgI (insoluble) iodine.","Oxygen has no direct test; its percentage is found by difference."]},{"q":[["15.8",18]],"s":["Destructive distillation: coal is heated strongly (about 1000 °C) in the absence of air; it decomposes into four main fractions.","Coal gas (H₂, CH₄, CO and others): used as a fuel for heating and lighting.","Ammoniacal liquor (aqueous ammonia and ammonium salts): treated with H₂SO₄ to give ammonium sulphate fertiliser.","Coal tar: a thick black liquid; fractional distillation gives benzene, toluene, phenol, naphthalene, anthracene and pitch — raw materials for dyes, drugs, explosives, plastics, perfumes and insecticides; pitch is used for road surfacing and roofing.","Coke (residue, nearly pure carbon): a smokeless fuel and a reducing agent in the extraction of iron; used to make water gas and producer gas."]},{"q":[["15.8",19]],"s":["Organic compounds are covalent; most do not ionise and are non-electrolytes.","They usually have low melting and boiling points; many are volatile liquids or gases.","Most are insoluble in water but soluble in organic solvents (alcohol, ether, benzene); many are combustible, burning to CO₂ and H₂O.","Their reactions are generally slow, involve molecules and often need heat or catalysts, giving side products.","Catenation and isomerism are common, so there is an enormous number of organic compounds; they show homologous series with similar properties."]},{"q":[["15.8",20]],"s":["A functional group is an atom or group of atoms in a molecule that is responsible for its characteristic chemical properties.","Classes by functional group: alkenes (C=C), alkynes (C≡C), alkyl halides (–X), alcohols (–OH), ethers (R–O–R), aldehydes (–CHO), ketones (>C=O), carboxylic acids (–COOH), esters (–COOR), amines (–NH₂), amides (–CONH₂), nitriles (–C≡N), nitro compounds (–NO₂), acid halides (–COX), acid anhydrides.","Examples: CH₃CH₂OH (ethanol, alcohol), CH₃CHO (ethanal, aldehyde), CH₃COCH₃ (propanone, ketone), CH₃COOH (ethanoic acid), CH₃NH₂ (methylamine).","All compounds with the same functional group form a homologous series and react in similar ways."]},{"q":[["15.8",21]],"s":["Organic compounds are classified by the arrangement of carbon atoms into open-chain and closed-chain compounds.","Open-chain (acyclic or aliphatic) compounds: carbon atoms form straight chains (n-butane) or branched chains (isobutane); they may be saturated or unsaturated.","Closed-chain (cyclic) compounds: (i) Homocyclic (carbocyclic) — rings contain only carbon atoms: alicyclic compounds (cyclopropane, cyclohexane) and aromatic compounds (benzene, naphthalene). (ii) Heterocyclic — rings containing one or more other atoms such as N, O or S (pyridine, furan, thiophene)."]}],"activities":[{"q":[["15.8",23]],"s":["Carbon and hydrogen: mix a little dry urea with dry copper(II) oxide in a hard-glass test tube and heat. Pass the gas into lime water — it turns milky (CO₂), so carbon is present. Droplets on the cooler part of the tube turn white anhydrous CuSO₄ blue (H₂O), so hydrogen is present.","Nitrogen: fuse urea with a small piece of sodium (Lassaigne's test), dissolve in water and filter. Boil the filtrate with FeSO₄ solution, add a few drops of FeCl₃ and acidify with dilute H₂SO₄ — a Prussian blue colour confirms nitrogen.","(Quick check: warming urea with NaOH solution gives ammonia, which turns moist red litmus blue.)"]}]}},"16":{"items":{"mcqs":[{"q":[["16.30",2],["16.30",3]],"s":["C₅H₁₂ has three structural isomers: n-pentane, isopentane (2-methylbutane) and neopentane (2,2-dimethylpropane)."],"inline":1,"c":1},{"q":[["16.30",4],["16.30",5]],"s":["Zinc removes the four bromine atoms from adjacent carbons C2 and C3: CH₃CBr₂CBr₂CH₃ + 2Zn → CH₃C≡CCH₃ + 2ZnBr₂.","The product is but-2-yne."],"inline":1,"c":1},{"q":[["16.30",6],["16.30",7]],"s":["Lindlar's catalyst (Pd on CaCO₃/BaSO₄, partly poisoned) adds one molecule of H₂ to the same side of the triple bond (syn addition).","It gives the cis-alkene (cis-but-2-ene). Na/liq. NH₃ gives the trans-alkene; H₂/Ni goes on to the alkane."],"inline":1,"c":1},{"q":[["16.30",8],["16.30",9]],"s":["HC≡CH + HCl → CH₂=CHCl (vinyl chloride); with excess HCl, a second molecule adds by Markovnikov's rule to the carbon already bearing Cl.","CH₂=CHCl + HCl → CH₃CHCl₂, 1,1-dichloroethane."],"inline":1,"c":3},{"q":[["16.30",10],["16.30",11]],"s":["Homolytic fission divides the bonding pair equally, one electron to each atom.","R–H → R• + H•, giving an alkyl free radical."],"inline":1,"c":2},{"q":[["16.30",12],["16.30",13]],"s":["–NH₂, –OH and –OCH₃ are activating o/p-directors.","–Cl withdraws electrons inductively (deactivating) but donates lone pairs by resonance to the ortho/para positions (o/p-directing)."],"inline":1,"c":3},{"q":[["16.30",14],["16.30",15]],"s":["Geometrical isomerism needs two different groups on each carbon of the double bond.","But-1-ene has two H on C1; 2-methylbut-2-ene and 2-methylpropene have two CH₃ on one carbon. None of them shows it."],"inline":1,"c":3},{"q":[["16.30",16],["16.30",17]],"s":["C₂H₆O has two isomers: ethanol CH₃CH₂OH and dimethyl ether CH₃OCH₃ (functional group isomers)."],"inline":1,"c":0},{"q":[["16.30",18],["16.30",19]],"s":["Markovnikov addition: H adds to the CH₂ carbon, giving the more stable tertiary carbocation (CH₃)₃C⁺.","Br⁻ then adds: (CH₃)₂C=CH₂ + HBr → (CH₃)₃CBr, tert-butyl bromide."],"inline":1,"c":3},{"q":[["16.30",20],["16.30",21]],"s":["Ozonolysis splits C=C into two C=O compounds. Acetone (CH₃)₂C=O and acetaldehyde CH₃CH=O come from (CH₃)₂C=CHCH₃.","That alkene is 2-methylbut-2-ene."],"inline":1,"c":2},{"q":[["16.30",22],["16.30",23]],"s":["Alcoholic KOH removes HX from an alkyl halide (β-elimination) to form an alkene.","Aqueous KOH instead gives substitution (an alcohol)."],"inline":1,"c":2},{"q":[["16.30",24],["16.30",25]],"s":["sec-Butyl bromide CH₃–CH(Br)–CH₂CH₃: C2 carries four different groups (H, Br, CH₃, C₂H₅).","It contains a chiral centre; the other isomers do not."],"inline":1,"c":2},{"q":[["16.30",26],["16.30",27]],"s":["In UV light Cl₂ splits into Cl• radicals, which remove a hydrogen from the side-chain CH₃ of toluene.","C₆H₅CH₂• + Cl₂ → C₆H₅CH₂Cl + Cl•: free-radical substitution."],"inline":1,"c":2},{"q":[["16.30",28],["16.30",29]],"s":["Sodium amide forms salts only with terminal alkynes, which have an acidic ≡C–H.","C₃H₄ (propyne, CH₃C≡CH) gives CH₃C≡C⁻Na⁺ + NH₃."],"inline":1,"c":1},{"q":[["16.30",30],["16.30",31]],"s":["–NO₂ is a strongly deactivating meta-directing group.","Chlorination with Cl₂/AlCl₃ gives mainly m-chloronitrobenzene."],"inline":1,"c":1}],"shortQuestions":[{"q":[["16.30",33]],"s":["Aliphatic hydrocarbons are open-chain (or non-aromatic cyclic) hydrocarbons — alkanes, alkenes, alkynes and cycloalkanes; unsaturated ones readily undergo addition reactions.","Aromatic hydrocarbons contain one or more benzene rings with a delocalised ring of π electrons (4n + 2 π electrons); they are unusually stable and prefer substitution to addition, e.g. benzene, toluene, naphthalene."]},{"q":[["16.30",34]],"s":["Plane-polarised light is light whose electric vibrations occur in only one plane. Monochromatic light has a single wavelength (e.g. the sodium D line, 589 nm).","Plane-polarised monochromatic light is produced by passing light from a sodium lamp through a Nicol prism or Polaroid; it is used in a polarimeter to measure the optical rotation of chiral (optically active) compounds."]},{"q":[["16.30",35]],"s":["Bromine water (or Br₂ in CCl₄) test: the reddish-brown colour is discharged rapidly as bromine adds across the C=C bond: CH₂=CH₂ + Br₂ → CH₂Br–CH₂Br.","Baeyer's test: cold, dilute alkaline KMnO₄ loses its purple colour and a brown precipitate of MnO₂ forms as the alkene is oxidised to a diol."]},{"q":[["16.30",36]],"s":["In benzene the six π electrons are delocalised over the ring, giving a resonance (aromatic) stabilisation of about 150 kJ mol⁻¹; addition would destroy this, so benzene is less reactive than ethene, whose localised π electrons are easily attacked.","However benzene still has a cloud of π electrons available for electrophiles (it undergoes substitution), whereas ethane has only strong σ bonds; so benzene is more reactive than ethane."]},{"q":[["16.30",37]],"s":["Halogens are highly electronegative: they withdraw electron density from the ring by the inductive (−I) effect, making it less reactive than benzene — so they are deactivating.","But their lone pairs are donated into the ring by resonance (+R), increasing electron density at the ortho and para positions and stabilising the arenium ions formed by o/p attack — so they are ortho/para directing."]},{"q":[["16.30",38]],"s":["A chiral carbon (asymmetric carbon, stereocentre) is a carbon atom attached to four different atoms or groups.","Chirality is a property of the whole molecule: it is non-superimposable on its mirror image. Usually a chiral carbon makes a molecule chiral, but a molecule may be chiral without one (some allenes and biphenyls) or achiral despite having them (meso compounds)."]},{"q":[["16.30",39]],"s":["But-1-ene is CH₂=CH–CH₂CH₃. Carbon-1 of the double bond carries two identical hydrogen atoms.","Geometrical (cis–trans) isomerism needs two different groups on each double-bonded carbon, so but-1-ene has no geometrical isomers."]},{"q":[["16.30",40]],"s":["In cyclopropane the C–C–C angle is 60°, far from the normal tetrahedral angle of 109.5°; this causes large angle strain (Baeyer strain) and poor overlap of orbitals (bent 'banana' bonds).","These weak, strained bonds break easily; ring opening relieves the strain, so cyclopropane undergoes addition reactions (with H₂, Br₂, HBr) that propane does not."]},{"q":[["16.30",41]],"s":["Terminal (1-)alkynes have an acidic hydrogen on the triple-bonded carbon (≡C–H).","With ammoniacal silver nitrate they give a white precipitate of a silver alkynide, and with ammoniacal copper(I) chloride a red precipitate: HC≡CH + 2[Ag(NH₃)₂]⁺ → AgC≡CAg↓ + 2NH₄⁺ + 2NH₃.","Non-terminal alkynes (e.g. but-2-yne) give no precipitate."]},{"q":[["16.30",42]],"s":["Tautomerism: two real, separable isomers exist in dynamic equilibrium and differ in the position of an atom (usually H) as well as of electrons, e.g. keto ⇌ enol forms of acetoacetic ester.","Resonance: a single real molecule is represented by several structures that differ only in the arrangement of electrons, not of atoms; the contributing structures do not exist separately — the real molecule is their hybrid (e.g. benzene)."]}],"longQuestions":[{"q":[["16.30",44],["16.30",45],["16.30",46]],"s":["(a) Chlorination of methane is a free-radical chain reaction in UV light or at 300 °C. Initiation: Cl₂ → 2Cl•. Propagation: Cl• + CH₄ → •CH₃ + HCl; •CH₃ + Cl₂ → CH₃Cl + Cl• (the Cl• continues the chain). Termination: Cl• + Cl• → Cl₂; •CH₃ + Cl• → CH₃Cl; •CH₃ + •CH₃ → C₂H₆. With excess chlorine, further substitution gives CH₂Cl₂, CHCl₃ and CCl₄.","(b) Cycloalkanes (CₙH₂ₙ) are saturated ring hydrocarbons. In cyclopropane (60°) and cyclobutane (≈ 90°) the bond angles are much smaller than 109.5°, causing angle strain; they are reactive and undergo ring-opening addition (e.g. cyclopropane + H₂/Ni → propane; + Br₂ → 1,3-dibromopropane). Cyclopentane and cyclohexane (puckered 'chair' form, 109.5° angles) are almost strain-free and react like alkanes, by substitution.","(c) Physical properties of alkanes and cycloalkanes: non-polar, colourless; insoluble in water but soluble in organic solvents; less dense than water. C₁–C₄ are gases, C₅–C₁₇ liquids and higher members waxy solids. Boiling points rise with molecular mass (stronger van der Waals forces) and fall with branching. Cycloalkanes have higher boiling points, melting points and densities than the corresponding open-chain alkanes."]},{"q":[["16.30",47],["16.30",48],["16.30",49]],"s":["(a) Hydrocarbons are compounds containing only carbon and hydrogen. Classes: (i) aliphatic (open-chain) — saturated alkanes CₙH₂ₙ₊₂ (methane, ethane) and unsaturated alkenes CₙH₂ₙ (ethene) and alkynes CₙH₂ₙ₋₂ (ethyne); (ii) alicyclic — cycloalkanes and cycloalkenes (cyclohexane); (iii) aromatic — benzene and its homologues (benzene, toluene, naphthalene).","(b)(i) Dehydration of ethyl alcohol with excess concentrated H₂SO₄ at 170 °C (or Al₂O₃ at 350 °C): CH₃CH₂OH → CH₂=CH₂ + H₂O.","(ii) Dehydrohalogenation of ethyl bromide by boiling with alcoholic KOH: CH₃CH₂Br + KOH(alc) → CH₂=CH₂ + KBr + H₂O.","(c) Relative stability of alkenes (from heats of hydrogenation): the more alkyl groups attached to the double-bonded carbons, the more stable the alkene (hyperconjugation and inductive donation): R₂C=CR₂ > R₂C=CHR > R₂C=CH₂ ≈ RCH=CHR > RCH=CH₂ > CH₂=CH₂. Trans-alkenes are more stable than cis-alkenes because the bulky groups are farther apart (less steric strain)."]},{"q":[["16.30",50],["16.30",51],["16.31",0]],"s":["(a) Preparation of alkynes: (i) Dehydrohalogenation of vicinal dihalides with alcoholic KOH (then NaNH₂): CH₂Br–CH₂Br + 2KOH → HC≡CH + 2KBr + 2H₂O. (ii) Dehalogenation of tetrahalides with zinc: CHBr₂–CHBr₂ + 2Zn → HC≡CH + 2ZnBr₂. (Also: CaC₂ + 2H₂O → HC≡CH + Ca(OH)₂.)","(b) Acidity: the ≡C–H carbon is sp-hybridised (50% s-character), so it is more electronegative and holds the bonding pair closer, letting H leave as H⁺ (pKa ≈ 25, more acidic than alkenes and alkanes). Terminal alkynes form salts: HC≡CH + NaNH₂ → HC≡C⁻Na⁺ + NH₃; 2HC≡CH + 2Na → 2HC≡CNa + H₂. Distinction: terminal alkynes give a white precipitate with ammoniacal AgNO₃ and a red precipitate with ammoniacal Cu₂Cl₂; non-terminal alkynes do not.","(c) From an alkene (ethene as example): (i) vicinal dihalide — add Br₂ in CCl₄: CH₂=CH₂ + Br₂ → CH₂Br–CH₂Br. (ii) Alcohol — hydration with dilute H₂SO₄ (or via concentrated H₂SO₄ then water): CH₂=CH₂ + H₂O → CH₃CH₂OH. (iii) Aldehydes and ketones — ozonolysis: alkene + O₃ → ozonide, then Zn/H₂O, e.g. CH₃CH=CHCH₃ → 2CH₃CHO; (CH₃)₂C=C(CH₃)₂ → 2(CH₃)₂CO. (iv) Epoxide — catalytic oxidation of ethene with O₂ over Ag at about 250 °C, or reaction with a peroxyacid: CH₂=CH₂ + ½O₂ → ethylene oxide (oxirane)."]},{"q":[["16.31",1],["16.31",2],["16.31",3]],"s":["(a) Molecular-orbital structure: each carbon is sp²-hybridised; sp² orbitals form C–C σ bonds and C–H σ bonds at 120°, making a flat hexagonal ring. Each carbon also has an unhybridised 2p orbital perpendicular to the ring. The six p orbitals overlap sideways all round the ring to form six π molecular orbitals; the three bonding MOs hold the six π electrons, which are delocalised as two rings of electron density above and below the plane. Hence all C–C bonds are equal (139 pm) and benzene has extra (resonance) stability of about 150 kJ mol⁻¹.","(b) Electrophilic substitution mechanism: (1) Generation of the electrophile, e.g. HNO₃ + 2H₂SO₄ → NO₂⁺ + H₃O⁺ + 2HSO₄⁻. (2) The electrophile attacks the π cloud, forming a resonance-stabilised arenium ion (σ-complex) — the slow, rate-determining step. (3) A base (HSO₄⁻) removes H⁺ from the sp³ carbon, restoring the aromatic ring: C₆H₆ + NO₂⁺ → C₆H₅NO₂ + H⁺.","(c) (i) Acetophenone (Friedel–Crafts acylation): C₆H₆ + CH₃COCl —AlCl₃→ C₆H₅COCH₃ + HCl. (ii) Toluene (Friedel–Crafts alkylation): C₆H₆ + CH₃Cl —AlCl₃→ C₆H₅CH₃ + HCl. (iii) Nitrobenzene: C₆H₆ + HNO₃ —conc. H₂SO₄, 50–55 °C→ C₆H₅NO₂ + H₂O. (iv) Benzenesulphonic acid: C₆H₆ + H₂SO₄ (fuming, SO₃) → C₆H₅SO₃H + H₂O. (v) Chlorobenzene: C₆H₆ + Cl₂ —FeCl₃→ C₆H₅Cl + HCl. (vi) Cyclohexane: C₆H₆ + 3H₂ —Ni, 150–200 °C→ C₆H₁₂."]},{"q":[["16.31",4],["16.31",5],["16.31",6],["16.31",7],["16.31",8],["16.31",9],["16.31",10],["16.31",11]],"s":["(a) A substituent already on a benzene ring decides how fast and where a second group enters. Activating ortho/para directors donate electrons (+R or +I): –OH, –NH₂, –OR, –NHCOCH₃, –CH₃; they make the ring more reactive than benzene and stabilise the arenium ions for ortho/para attack. Deactivating meta directors withdraw electrons (−R, −I): –NO₂, –CN, –CHO, –COOH, –SO₃H, –CF₃; they make the ring less reactive, and ortho/para attack is especially destabilised, so substitution occurs at meta. Halogens are deactivating (−I) but ortho/para directing (+R). E.g. phenol nitrates easily at o/p; nitrobenzene nitrates slowly at meta.","(b) Structural (condensed) formulas: (i) 3-ethyl-4-methyloctane: CH₃CH₂CH(C₂H₅)CH(CH₃)CH₂CH₂CH₂CH₃. (ii) 4-isopropyldecane: CH₃CH₂CH₂CH[CH(CH₃)₂](CH₂)₅CH₃. (iii) sec-butylcycloheptane: a cycloheptane ring carrying –CH(CH₃)CH₂CH₃. (iv) 2,3-dimethyl-4-propylnonane: CH₃CH(CH₃)CH(CH₃)CH(CH₂CH₂CH₃)(CH₂)₄CH₃.","(iv) 2,4,4-trimethylhex-2-ene: (CH₃)₂C=CH–C(CH₃)₂–CH₂CH₃. (v) cis-hex-3-ene: CH₃CH₂–CH=CH–CH₂CH₃ with both ethyl groups on the same side of the double bond. (vi) Phenanthrene: C₁₄H₁₀, three benzene rings fused in an angular arrangement. (vii) Hex-2-yne: CH₃C≡CCH₂CH₂CH₃.","(viii) 1,2-dimethyl-4-propylbenzene: a benzene ring with CH₃ groups at C1 and C2 and –CH₂CH₂CH₃ at C4. (ix) Cyclopropylbenzene: C₆H₅–C₃H₅ (a phenyl group attached to a cyclopropane ring)."]}],"activities":[{"q":[["16.31",13]],"s":["Observation: the brown (or yellow-brown) colour of the bromine reagent disappears almost at once, drop after drop, until the C=C bonds are used up.","Reason: bromine adds across the carbon–carbon double bond to form a colourless vicinal dibromide, e.g. CH₂=CH₂ + Br₂ → CH₂Br–CH₂Br.","Conclusion: rapid decolourisation shows unsaturation (C=C or C≡C). A saturated compound leaves the brown colour unchanged (without UV light)."]}]}},"17":{"items":{"mcqs":[{"q":[["17.15",2],["17.15",3]],"s":["CH₃MgI adds to the C=O of acetone: (CH₃)₂C=O + CH₃MgI → (CH₃)₃C–OMgI.","Hydrolysis gives (CH₃)₃C–OH, tert-butyl alcohol (a ketone gives a tertiary alcohol)."],"inline":1,"c":0},{"q":[["17.15",4],["17.15",5]],"s":["Reactivity depends on how easily the C–X bond breaks: C–I is the weakest bond and I⁻ the best leaving group.","Order: R–I > R–Br > R–Cl > R–F, so C₂H₅I is the most reactive."],"inline":1,"c":1},{"q":[["17.15",6],["17.15",7]],"s":["An electrophile ('electron-loving') is electron-deficient and accepts an electron pair, e.g. H⁺, NO₂⁺, carbocations."],"inline":1,"c":0},{"q":[["17.15",8],["17.15",9]],"s":["The carbon bearing X is attached to only one other carbon (R).","R–CH₂–X is a primary alkyl halide."],"inline":1,"c":0},{"q":[["17.15",10],["17.15",11]],"s":["A carbon with only six valence electrons, three bonds and a positive charge is a carbocation (carbonium ion)."],"inline":1,"c":0},{"q":[["17.15",12],["17.15",13]],"s":["A Grignard reagent is an alkylmagnesium halide, R–Mg–X (e.g. CH₃MgI), prepared from RX and Mg in dry ether."],"inline":1,"c":3},{"q":[["17.15",14],["17.15",15]],"s":["An ester reacts with two moles of Grignard reagent: the first gives a ketone, the second adds to the ketone.","CH₃COOC₂H₅ + 2RMgX, then hydrolysis → CH₃C(R)₂OH, a tertiary alcohol."],"inline":1,"c":2},{"q":[["17.15",16],["17.15",17]],"s":["A nucleophile ('nucleus-loving') has a lone pair that it donates to an electron-deficient centre.","An electron-pair donor is a nucleophile (a Lewis base)."],"n":"The book prints the label b. twice; 'Nucleophile' is the third choice (c).","inline":1,"r":[["b. ","c. ",2]],"c":2},{"q":[["17.15",18],["17.15",19]],"s":["In a secondary alkyl halide R₂CH–X the carbon bearing the halogen is bonded directly to two other carbon atoms."],"inline":1,"c":1},{"q":[["17.15",20],["17.15",21]],"s":["SN1 goes through a planar carbocation that the nucleophile can attack from either face.","This gives racemisation — usually partial, with slightly more inversion because the leaving group shields one face."],"inline":1,"c":2},{"q":[["17.15",22],["17.15",23]],"s":["Protic solvents have H attached to O or N (water, ethanol, formic acid) and can donate hydrogen bonds.","Acetone has no O–H or N–H, so it is a (polar) aprotic solvent."],"inline":1,"c":0},{"q":[["17.15",24],["17.15",25]],"s":["The rate of SN1 depends only on the slow ionisation step: rate = k[RX].","The nucleophile is not involved in that step, so its nature does not affect the SN1 rate; solvent and carbocation stability do."],"inline":1,"c":2},{"q":[["17.15",26],["17.15",27]],"s":["C₂H₅MgBr + CO₂ → C₂H₅COOMgBr; hydrolysis gives C₂H₅COOH.","The product (three carbons) is propanoic acid."],"inline":1,"c":1},{"q":[["17.15",28],["17.15",29]],"s":["In CH₃Cl the carbon is sp³-hybridised with four σ bonds.","Its geometry is tetrahedral (bond angles ≈ 109.5°)."],"inline":1,"c":3},{"q":[["17.15",30],["17.15",31]],"s":["Bulky groups around the α-carbon hinder backside attack by a nucleophile (SN2), but a base can still remove a β-hydrogen.","So crowding favours elimination."],"inline":1,"c":0}],"shortQuestions":[{"q":[["17.15",33]],"s":["Nucleophilic substitution: an electron-rich nucleophile (OH⁻, CN⁻, NH₃) attacks an electron-deficient carbon and replaces a leaving group, e.g. CH₃Br + OH⁻ → CH₃OH + Br⁻; typical of alkyl halides; mechanisms SN1 and SN2.","Electrophilic substitution: an electron-deficient electrophile (NO₂⁺, Br⁺, R⁺) attacks the electron-rich π cloud of an aromatic ring and replaces a hydrogen via an arenium ion, e.g. C₆H₆ + NO₂⁺ → C₆H₅NO₂ + H⁺; typical of benzene."]},{"q":[["17.15",34]],"s":["In an alkyl halide the C–X bond is polar (Cδ+–Xδ−): the carbon is electron-deficient, so it attracts nucleophiles, and X⁻ is a good leaving group.","Benzene has an electron-rich delocalised π cloud that repels nucleophiles but attracts electrophiles; substitution of an H (rather than addition) keeps the stable aromatic ring intact. So benzene undergoes electrophilic substitution."]},{"q":[["17.15",35]],"s":["A tertiary carbocation R₃C⁺ has three alkyl groups attached to the positive carbon.","Alkyl groups release electrons (+I effect) and stabilise the charge by hyperconjugation (overlap of C–H σ bonds with the empty p orbital), spreading out the positive charge.","More alkyl groups mean more stabilisation: 3° > 2° > 1° > CH₃⁺."]},{"q":[["17.15",36]],"s":["SN1 and E1 have the same slow (rate-determining) step: ionisation of the tertiary alkyl halide into a carbocation, favoured by the polar protic solvent: R–X → R⁺ + X⁻.","Both rates are therefore rate = k[RX] with the same k. Afterwards the carbocation either combines with a nucleophile (SN1) or loses a β-proton (E1) in fast steps, which decide only the product ratio, not the rate."]},{"q":[["17.15",37]],"s":["In a polar protic solvent (water, alcohol) the small, highly charged F⁻ is strongly hydrogen-bonded and surrounded by solvent molecules, so its lone pairs are not available — it is a weak nucleophile.","In a polar aprotic solvent (DMSO, acetone, DMF) anions are poorly solvated; F⁻ is 'naked', highly reactive and becomes a strong nucleophile."]},{"q":[["17.15",38]],"s":["In SN2 the nucleophile approaches from the side opposite to the leaving group (backside attack).","This avoids repulsion between the electron-rich nucleophile and the electron-rich leaving group, and lets the nucleophile overlap with the large back lobe of the C–X σ* orbital.","The three other groups flip over like an umbrella in a wind, so the configuration is inverted (Walden inversion)."]},{"q":[["17.15",39]],"s":["Reactivity depends on C–X bond strength and the stability of the leaving halide ion.","C–F is the strongest bond (≈ 485 kJ mol⁻¹) and F⁻ a poor leaving group, so alkyl fluorides are least reactive.","C–I is the weakest (≈ 240 kJ mol⁻¹) and the large, polarisable I⁻ is the best leaving group, so alkyl iodides are most reactive."]},{"q":[["17.15",40]],"s":["In the gas phase basicity follows the +I effect: 3° > 2° > 1°. In water the protonated amine is stabilised by hydrogen bonding with water.","R₂NH₂⁺ (from a secondary amine) has two N–H bonds to hydrogen-bond with water, but R₃NH⁺ has only one; tertiary amines are also more crowded around nitrogen.","Poorer solvation of R₃NH⁺ makes tertiary amines weaker bases than secondary amines in aqueous solution."]},{"q":[["17.15",41]],"s":["In CH₃⁺ the carbon forms only three σ bonds and has no lone pair; it is sp²-hybridised.","The three bonding pairs repel equally and lie in one plane at 120° (trigonal planar), with an empty p orbital perpendicular to the plane. A pyramidal shape would require a fourth electron pair (as in a carbanion)."]},{"q":[["17.15",42]],"s":["A nucleophile donates an electron pair to an electron-deficient carbon; nucleophilicity is a kinetic property (rate of attack).","A base donates an electron pair to a proton (H⁺); basicity is a thermodynamic property (position of equilibrium).","Every nucleophile is a Lewis base, but strength can differ: I⁻ is a good nucleophile but a weak base; (CH₃)₃CO⁻ is a strong base but a poor nucleophile (bulky)."]}],"longQuestions":[{"q":[["17.15",44],["17.15",45]],"s":["(a) Preparation of alkyl halides: (i) From alcohols with hydrogen halides: ROH + HX → RX + H₂O (HCl needs ZnCl₂, Lucas reagent). (ii) From alcohols with phosphorus halides: ROH + PCl₅ → RCl + POCl₃ + HCl; 3ROH + PBr₃ → 3RBr + H₃PO₃. (iii) With thionyl chloride (best, gaseous by-products): ROH + SOCl₂ —pyridine→ RCl + SO₂ + HCl. (iv) Addition of HX to alkenes (Markovnikov): CH₃CH=CH₂ + HBr → CH₃CHBrCH₃. (v) Free-radical halogenation of alkanes: CH₄ + Cl₂ —UV→ CH₃Cl + HCl. (vi) Halide exchange (Finkelstein): RCl + NaI —acetone→ RI + NaCl.","(b) Elimination (β-elimination, dehydrohalogenation): heating an alkyl halide with alcoholic KOH removes H from the β-carbon and X from the α-carbon to give an alkene: CH₃CH₂Br + KOH(alc) → CH₂=CH₂ + KBr + H₂O.","E2: one-step, concerted; the base removes the β-H as X leaves; rate = k[RX][base]; favoured by strong bases and requires anti-periplanar H and X. E1: two steps via a carbocation (slow ionisation, then loss of H⁺); rate = k[RX]; favoured by tertiary halides and polar protic solvents.","Saytzeff's rule: the more substituted alkene is the major product, e.g. 2-bromobutane gives mainly but-2-ene."]},{"q":[["17.16",0],["17.16",1]],"s":["(a) SN1 (unimolecular): Step 1 (slow): R₃C–X → R₃C⁺ + X⁻. Step 2 (fast): R₃C⁺ + Nu⁻ → R₃C–Nu. Rate = k[RX] (first order). The planar carbocation is attacked from either side, giving racemisation. Favoured by 3° halides, polar protic solvents and weak nucleophiles; rearrangements may occur.","SN2 (bimolecular): one step — the nucleophile attacks the carbon from the back while X leaves, through a transition state [Nu···C···X]⁻ with five groups around carbon. Rate = k[RX][Nu⁻] (second order). Inversion of configuration (Walden inversion). Favoured by methyl and 1° halides, strong nucleophiles and polar aprotic solvents; hindered by bulky groups.","(b)(i) Substrate: the molecule on which a reagent acts, e.g. the alkyl halide in a substitution reaction. (ii) Leaving group: the atom or group that departs from the substrate taking the bonding electron pair, e.g. Cl⁻, Br⁻, I⁻; good leaving groups are weak bases. (iii) Carbocation: an ion in which a carbon atom has only six valence electrons and a positive charge, bonded to three groups; sp²-hybridised and planar, e.g. (CH₃)₃C⁺."]},{"q":[["17.16",2],["17.16",3]],"s":["(a) Preparation: an alkyl (or aryl) halide is added to magnesium turnings in dry (anhydrous) ether: R–X + Mg —dry ether→ R–Mg–X (e.g. CH₃I + Mg → CH₃MgI). Moisture must be excluded because water destroys the reagent (RMgX + H₂O → RH + Mg(OH)X).","(b)(i) Aldehydes: formaldehyde gives a primary alcohol and other aldehydes give secondary alcohols. HCHO + CH₃MgI → CH₃CH₂OMgI → (H₃O⁺) CH₃CH₂OH; CH₃CHO + CH₃MgI → (CH₃)₂CHOMgI → (CH₃)₂CHOH.","(ii) Ketones give tertiary alcohols: (CH₃)₂CO + CH₃MgI → (CH₃)₃COMgI → (H₃O⁺) (CH₃)₃COH.","(iii) Esters react with two moles to give tertiary alcohols: CH₃COOC₂H₅ + CH₃MgI → CH₃COCH₃ (ketone) + C₂H₅OMgI; CH₃COCH₃ + CH₃MgI → (CH₃)₃COMgI → (CH₃)₃COH.","(iv) Carbon dioxide gives carboxylic acids: RMgX + CO₂ → RCOOMgX → (H₃O⁺) RCOOH, e.g. CH₃MgI → CH₃COOH."]},{"q":[["17.16",4],["17.16",5]],"s":["(a) Preparation of amines: (i) Ammonolysis of alkyl halides: RX + NH₃ → RNH₂ + HX (excess RX gives R₂NH, R₃N and R₄N⁺X⁻). (ii) Reduction of nitriles: RC≡N + 4[H] —LiAlH₄ or Na/C₂H₅OH→ RCH₂NH₂. (iii) Reduction of nitro compounds: C₆H₅NO₂ + 6[H] —Sn/HCl→ C₆H₅NH₂ + 2H₂O. (iv) Reduction of amides with LiAlH₄; Hofmann degradation: RCONH₂ + Br₂ + 4NaOH → RNH₂ + Na₂CO₃ + 2NaBr + 2H₂O.","Structure: nitrogen is sp³-hybridised; three σ bonds and a lone pair give a pyramidal shape with C–N–C angles of about 108°.","Basicity: the lone pair on N accepts a proton: RNH₂ + H₂O ⇌ RNH₃⁺ + OH⁻. Aliphatic amines are stronger bases than ammonia (+I effect of alkyl groups); in water the order is 2° > 1° ≈ 3° > NH₃. Aromatic amines (aniline) are weaker bases because the lone pair is delocalised into the ring.","(b) Reactions of amines: (i) with acids → salts: CH₃NH₂ + HCl → CH₃NH₃⁺Cl⁻. (ii) Alkylation with RX → 2°, 3° amines and quaternary salts. (iii) Acylation: CH₃NH₂ + CH₃COCl → CH₃NHCOCH₃ + HCl. (iv) With nitrous acid: 1° aliphatic amines give alcohols and N₂ gas; aromatic 1° amines give diazonium salts at 0–5 °C (C₆H₅NH₂ + HNO₂ + HCl → C₆H₅N₂⁺Cl⁻ + 2H₂O). (v) Carbylamine test: RNH₂ + CHCl₃ + 3KOH → RNC (foul-smelling isocyanide) + 3KCl + 3H₂O. (vi) Hinsberg test with benzenesulphonyl chloride."]},{"q":[["17.16",6],["17.16",7],["17.16",8],["17.16",9],["17.16",10],["17.16",11],["17.17",0],["17.17",1],["17.17",2]],"s":["(a) Carbocations are positively charged carbon species in which the carbon has six valence electrons and three bonds; they are sp²-hybridised and planar. Formation: (i) heterolysis of an alkyl halide in a polar solvent: (CH₃)₃C–Br → (CH₃)₃C⁺ + Br⁻; (ii) protonation of an alkene: CH₂=CH₂ + H⁺ → CH₃CH₂⁺; (iii) protonation of an alcohol followed by loss of water: (CH₃)₃COH + H⁺ → (CH₃)₃COH₂⁺ → (CH₃)₃C⁺ + H₂O.","(b) Stability order: tertiary > secondary > primary > methyl (3° > 2° > 1° > CH₃⁺). Alkyl groups donate electrons by the inductive effect and by hyperconjugation, dispersing the positive charge; more alkyl groups mean greater stability. Allylic and benzylic carbocations are especially stable because of resonance.","(c, d) Structural formulas: i. 3-methylpentane-2,3-diamine: CH₃–CH(NH₂)–C(CH₃)(NH₂)–CH₂–CH₃. ii. 2,3-dimethylhexane-2,3-diamine: (CH₃)₂C(NH₂)–C(CH₃)(NH₂)–CH₂CH₂CH₃. iii. 2-bromo-3-fluoro-2,3-dimethylpentane: (CH₃)₂CBr–CF(CH₃)–CH₂CH₃.","iv. 4-bromo-4-chloro-3-fluoro-2,3-dimethylhexane: CH₃–CH(CH₃)–CF(CH₃)–CBrCl–CH₂CH₃. v. 2-chloro-3,3-dimethylpentan-2-amine: CH₃–CCl(NH₂)–C(CH₃)₂–CH₂CH₃. (Part (c) prints no structures to be named, so only part (d) can be answered.)"]}],"activities":[{"q":[["17.17",4],["17.17",5],["17.17",6]],"s":["Primary amine: reacts with benzenesulphonyl chloride to give an N-alkylbenzenesulphonamide that still has an acidic N–H; it dissolves in NaOH as its sodium salt, so a single clear layer is seen. C₆H₅SO₂Cl + RNH₂ → C₆H₅SO₂NHR + HCl; C₆H₅SO₂NHR + NaOH → C₆H₅SO₂N⁻R Na⁺ + H₂O. Acidifying precipitates the sulphonamide.","Secondary amine: gives an N,N-dialkylsulphonamide C₆H₅SO₂NR₂ with no N–H; it is insoluble in NaOH, so two layers form, and the organic layer is also insoluble in dilute HCl.","Tertiary amine: has no N–H and does not form a sulphonamide; it stays as a separate layer in NaOH but dissolves in 5% HCl because it forms a soluble ammonium salt (R₃NH⁺Cl⁻).","So: one layer → primary; layer insoluble in both NaOH and HCl → secondary; layer soluble in HCl → tertiary."]}]}},"18":{"items":{"mcqs":[{"q":[["18.16",2],["18.16",3]],"s":["Isopropyl alcohol is (CH₃)₂CH–OH: the carbon carrying –OH is bonded to two other carbons.","It is a secondary alcohol (propan-2-ol)."],"inline":1,"c":1},{"q":[["18.16",4],["18.16",5]],"s":["Alcohols hydrogen-bond, so they boil higher than dimethyl ether; propanols (3 C) boil higher than ethanol (2 C).","Branching lowers the boiling point, so n-propyl alcohol (97 °C) is higher than isopropyl alcohol (82 °C)."],"inline":1,"c":2},{"q":[["18.16",6],["18.16",7]],"s":["Trimethylene glycol is HO–CH₂–CH₂–CH₂–OH (propane-1,3-diol): the two –OH groups are on carbons 1 and 3.","It is neither a vic-diol (adjacent carbons) nor a gem-diol (same carbon), and it has only two –OH groups. None of these."],"inline":1,"c":3},{"q":[["18.16",8],["18.16",9]],"s":["Periodic acid cleaves the C–C bond between the two –OH carbons: HOCH₂–CH₂OH + HIO₄ → 2HCHO + HIO₃ + H₂O.","The product is formaldehyde."],"inline":1,"c":0},{"q":[["18.16",10],["18.16",11]],"s":["A positively charged oxygen bonded to three atoms (like H₃O⁺ or R₂OH⁺) is an oxonium ion."],"inline":1,"c":1},{"q":[["18.16",12],["18.16",13]],"s":["Strong oxidants (acidified dichromate, permanganate) carry a primary alcohol on to the carboxylic acid.","Pyridinium chlorochromate (PCC) in CH₂Cl₂ stops at the aldehyde."],"inline":1,"c":3},{"q":[["18.16",14],["18.16",15]],"s":["In benzyl alcohol C₆H₅CH₂OH the –OH is on a side-chain carbon attached to a benzene ring — an aromatic alcohol.","p-Cresol has –OH directly on the ring, so it is a phenol."],"inline":1,"c":2},{"q":[["18.16",16],["18.16",17]],"s":["Natural gas (methane) is odourless; a little ethanethiol (C₂H₅SH), which has a strong smell, is added so that leaks can be detected."],"inline":1,"c":1},{"q":[["18.16",18],["18.16",19]],"s":["Lucas reagent reacts fastest with tertiary alcohols (via a stable 3° carbocation).","2-Methyl-2-propanol (tert-butyl alcohol) is tertiary, so it reacts at once."],"inline":1,"c":2},{"q":[["18.16",20],["18.16",21]],"s":["The ether oxygen accepts a proton from concentrated H₂SO₄: (C₂H₅)₂O + H₂SO₄ → (C₂H₅)₂OH⁺ HSO₄⁻.","An oxonium ion (salt) is formed, so ether dissolves in cold concentrated H₂SO₄."],"inline":1,"c":1},{"q":[["18.16",22],["18.16",23]],"s":["Lucas reagent is anhydrous ZnCl₂ dissolved in concentrated HCl."],"inline":1,"c":1},{"q":[["18.16",24],["18.16",25]],"s":["2ROH + 2Na → 2RO⁻Na⁺ + H₂.","A sodium alkoxide is formed, with hydrogen gas."],"inline":1,"c":2},{"q":[["18.16",26],["18.16",27]],"s":["On warming in water: C₆H₅N₂⁺Cl⁻ + H₂O → C₆H₅OH + N₂ + HCl.","Hydrolysis gives phenol."],"inline":1,"c":0},{"q":[["18.16",28],["18.16",29]],"s":["A secondary alcohol R₂CHOH loses two hydrogens on oxidation.","It gives a ketone R₂C=O."],"inline":1,"c":3},{"q":[["18.16",30],["18.16",31]],"s":["R–OH + HCl —ZnCl₂→ R–Cl + H₂O. The alkyl chloride is insoluble in the reagent.","It separates as tiny droplets, making the solution cloudy."],"inline":1,"c":0}],"shortQuestions":[{"q":[["18.16",33]],"s":["In an alcohol the –OH group is attached to a saturated (sp³) carbon of an alkyl group, e.g. CH₃CH₂OH; in a phenol it is attached directly to a carbon of a benzene ring (sp²), e.g. C₆H₅OH.","As a result phenol is weakly acidic (its anion is resonance-stabilised) and reacts with NaOH, gives a violet colour with FeCl₃ and readily undergoes ring substitution; alcohols are neutral and do not react with NaOH."]},{"q":[["18.16",34]],"s":["C₄H₉OH has four structural isomeric alcohols:","CH₃CH₂CH₂CH₂OH — n-butyl alcohol, butan-1-ol (1°).","CH₃CH(OH)CH₂CH₃ — sec-butyl alcohol, butan-2-ol (2°; it also has two enantiomers).","(CH₃)₂CHCH₂OH — isobutyl alcohol, 2-methylpropan-1-ol (1°).","(CH₃)₃COH — tert-butyl alcohol, 2-methylpropan-2-ol (3°)."]},{"q":[["18.16",35]],"s":["Lucas reagent is anhydrous ZnCl₂ in concentrated HCl. The alcohol is shaken with the reagent at room temperature; it is converted into an alkyl chloride, which is insoluble and makes the solution cloudy.","Tertiary alcohols give cloudiness immediately; secondary alcohols within about 5 minutes; primary alcohols show no cloudiness at room temperature (only on heating). The rate follows carbocation stability, 3° > 2° > 1°."]},{"q":[["18.16",36]],"s":["When phenol loses H⁺, the negative charge on the phenoxide ion is delocalised over the benzene ring by resonance (into the ortho and para positions), which stabilises it.","In an alkoxide ion RO⁻ the charge stays on oxygen, and the alkyl group (+I) even intensifies it. So phenol (pKa ≈ 10) ionises much more than alcohols (pKa ≈ 16–18)."]},{"q":[["18.16",37]],"s":["Alcohols are classified by the number of carbon atoms bonded to the carbon that carries –OH.","Primary (1°): one carbon (or none), RCH₂OH, e.g. ethanol. Secondary (2°): two carbons, R₂CHOH, e.g. propan-2-ol. Tertiary (3°): three carbons, R₃COH, e.g. 2-methylpropan-2-ol."]},{"q":[["18.16",38]],"s":["In alcohols and ethers the lone pairs on oxygen are localised and freely available, so the oxygen readily accepts a proton to form an oxonium ion (ROH₂⁺, R₂OH⁺).","In phenol the oxygen lone pairs are partly delocalised into the benzene ring by resonance, so they are less available for bonding with H⁺. Phenol is therefore much harder to protonate."]},{"q":[["18.16",39]],"s":["Heating a mixture of two different alcohols R–OH and R′–OH with concentrated H₂SO₄ gives a mixture of three ethers (R–O–R, R′–O–R′ and R–O–R′), which are difficult to separate; secondary and tertiary alcohols also dehydrate to alkenes.","So asymmetric (mixed) ethers are made by Williamson's synthesis instead: R–ONa + R′–X → R–O–R′ + NaX."]},{"q":[["18.16",40]],"s":["Alkene: bromine adds across the C=C bond; the brown colour disappears but no precipitate forms (a colourless dibromide), e.g. CH₂=CH₂ + Br₂ → CH₂Br–CH₂Br.","Phenol: bromine substitutes on the highly activated ring at room temperature without a catalyst; the colour disappears and a white precipitate of 2,4,6-tribromophenol forms, with HBr: C₆H₅OH + 3Br₂ → C₆H₂Br₃OH↓ + 3HBr."]},{"q":[["18.16",41]],"s":["The diazonium group –N₂⁺ can leave as nitrogen gas, N₂, an extremely stable molecule (strong triple bond) — an excellent leaving group, and its escape is favoured by the increase in entropy.","Benzenediazonium salts are stabilised only slightly by resonance with the ring, so they are stable only at 0–5 °C. On warming they lose N₂ and the aryl cation is attacked by water, giving phenol: C₆H₅N₂⁺ + H₂O → C₆H₅OH + N₂ + H⁺."]},{"q":[["18.16",42]],"s":["Oxidation of an alcohol removes the hydrogen of –OH and a hydrogen from the carbon bearing –OH (the carbinol carbon) to form C=O.","In a tertiary alcohol R₃C–OH the carbinol carbon has no hydrogen, so it cannot be oxidised without breaking a C–C bond; it resists mild oxidising agents (only drastic oxidation degrades the molecule)."]}],"longQuestions":[{"q":[["18.16",44],["18.16",45],["18.16",46]],"s":["(a) Dehydration of alcohol: ethanol in excess is heated with concentrated H₂SO₄ at about 140 °C: 2C₂H₅OH → C₂H₅–O–C₂H₅ + H₂O. Mechanism: the alcohol is protonated (C₂H₅OH₂⁺); a second ethanol molecule attacks it (SN2), losing water; then loss of H⁺ gives the ether. (At 170 °C ethene is formed instead.)","Williamson's synthesis: sodium ethoxide reacts with ethyl bromide (SN2): C₂H₅ONa + C₂H₅Br → C₂H₅OC₂H₅ + NaBr. It is suitable for symmetrical and unsymmetrical ethers (the halide should be primary).","(b) Reactions: (i) with hot concentrated HI: C₂H₅OC₂H₅ + HI → C₂H₅OH + C₂H₅I; with excess HI, 2C₂H₅I + H₂O. (ii) With cold concentrated H₂SO₄ it forms a soluble oxonium salt (C₂H₅)₂OH⁺HSO₄⁻; with PCl₅ on heating: C₂H₅OC₂H₅ + PCl₅ → 2C₂H₅Cl + POCl₃. (Ether slowly forms explosive peroxides in air.)","(c) Physical properties: colourless, volatile liquid with a sweet smell; boiling point 34.6 °C (lower than isomeric alcohols, since ethers cannot form hydrogen bonds among themselves); slightly soluble in water (H-bonds with water) but miscible with organic solvents; good solvent for fats and oils; less dense than water; highly flammable; once used as an anaesthetic."]},{"q":[["18.16",47],["18.16",48]],"s":["(a) Phenols are compounds in which an –OH group is attached directly to a carbon of an aromatic ring, e.g. phenol C₆H₅OH, cresols. Preparation: (i) From benzenesulphonic acid: fuse sodium benzenesulphonate with NaOH: C₆H₅SO₃Na + 2NaOH → C₆H₅ONa + Na₂SO₃ + H₂O, then acidify: C₆H₅ONa + HCl → C₆H₅OH + NaCl. (ii) Dow process: C₆H₅Cl + 2NaOH —350 °C, 200 atm→ C₆H₅ONa + NaCl + H₂O, then acidify. (iii) From benzenediazonium chloride by warming with water: C₆H₅N₂Cl + H₂O → C₆H₅OH + N₂ + HCl. (iv) From cumene: cumene is oxidised to cumene hydroperoxide, which with dilute acid gives phenol and acetone.","(b) Acidic behaviour: phenol is a weak acid (pKa ≈ 10): C₆H₅OH + H₂O ⇌ C₆H₅O⁻ + H₃O⁺. It reacts with Na (H₂ evolved) and with NaOH: C₆H₅OH + NaOH → C₆H₅ONa + H₂O, but it is weaker than carbonic acid and does not liberate CO₂ from NaHCO₃.","Reason: the phenoxide ion is stabilised by resonance, the negative charge spreading over the ortho and para carbons. Electron-withdrawing groups (–NO₂) increase acidity (2,4,6-trinitrophenol, picric acid, is quite strong); electron-donating groups (–CH₃) decrease it."]},{"q":[["18.17",0]],"s":["Structure: in phenol the –OH is bonded to an sp² carbon of the benzene ring. A lone pair on oxygen overlaps with the ring π system (resonance), giving the C–O bond partial double-bond character (136 pm, shorter than in alcohols) and increasing electron density at the ortho and para positions. The molecule is planar and the O–H is polar, so phenol forms hydrogen bonds (m.p. 41 °C, b.p. 182 °C, moderately soluble in water).","Reactions of the –OH group: acidic — with Na and NaOH forms sodium phenoxide; esterification — C₆H₅OH + CH₃COCl → C₆H₅OCOCH₃ + HCl; ether formation — C₆H₅ONa + CH₃I → C₆H₅OCH₃ + NaI; FeCl₃ test — violet colour; reduction with zinc dust gives benzene: C₆H₅OH + Zn → C₆H₆ + ZnO.","Ring (electrophilic substitution) reactions — highly activated, ortho/para: bromination with bromine water gives a white precipitate of 2,4,6-tribromophenol; dilute HNO₃ gives o- and p-nitrophenol, concentrated HNO₃ gives picric acid; sulphonation gives o-/p-hydroxybenzenesulphonic acid.","Other reactions: Kolbe's reaction — sodium phenoxide + CO₂ (125 °C, pressure), then acid, gives salicylic acid; condensation with formaldehyde gives bakelite; hydrogenation (Ni) gives cyclohexanol."]},{"q":[["18.17",1],["18.17",2]],"s":["(a) Structure: alcohols contain –OH bonded to an sp³ carbon; oxygen is sp³-hybridised with two lone pairs and a C–O–H angle of about 105°. The O–H bond is polar, so alcohols form hydrogen bonds (higher boiling points; lower alcohols miscible with water).","Synthesis: (i) hydration of alkenes: CH₂=CH₂ + H₂O —H₂SO₄→ CH₃CH₂OH; (ii) hydrolysis of alkyl halides: RX + KOH(aq) → ROH + KX; (iii) reduction of aldehydes and ketones with LiAlH₄, NaBH₄ or H₂/Ni (aldehyde → 1°, ketone → 2°); (iv) Grignard reagents with carbonyl compounds; (v) fermentation: C₆H₁₂O₆ —yeast→ 2C₂H₅OH + 2CO₂.","Reactions: with Na → alkoxide + H₂; with HX, PCl₅, PCl₃ or SOCl₂ → alkyl halides; dehydration with concentrated H₂SO₄ (170 °C → alkene, 140 °C → ether); oxidation — 1° → aldehyde → carboxylic acid, 2° → ketone, 3° resistant; esterification: RCOOH + R′OH ⇌ RCOOR′ + H₂O (H₂SO₄ catalyst).","(b) Alcohols are very weakly acidic because the O–H bond is polar: they react with active metals releasing hydrogen, 2C₂H₅OH + 2Na → 2C₂H₅ONa + H₂. They are weaker acids than water (the alkyl group's +I effect destabilises the alkoxide ion), so they do not turn blue litmus red or react with NaOH."]},{"q":[["18.17",3],["18.17",4],["18.17",5],["18.17",6],["18.17",7],["18.17",8],["18.17",9],["18.17",10],["18.17",11]],"s":["(a) From Grignard reagents and carbonyl compounds, followed by hydrolysis: formaldehyde gives primary alcohols — HCHO + CH₃MgI → CH₃CH₂OMgI → CH₃CH₂OH; other aldehydes give secondary alcohols — CH₃CHO + CH₃MgI → (CH₃)₂CHOH; ketones give tertiary alcohols — (CH₃)₂CO + CH₃MgI → (CH₃)₃COH. (Esters give tertiary alcohols with two moles of RMgX.)","(b)(i) Ethene: C₂H₅OH —conc. H₂SO₄, 170 °C→ CH₂=CH₂ + H₂O. (ii) Ethyl acetate: CH₃COOH + C₂H₅OH ⇌ (conc. H₂SO₄) CH₃COOC₂H₅ + H₂O. (iii) Acetone: oxidation of propan-2-ol, (CH₃)₂CHOH + [O] —K₂Cr₂O₇/H₂SO₄→ (CH₃)₂CO + H₂O (or Cu at 300 °C). (iv) Formaldehyde: oxidation of methanol, CH₃OH + [O] → HCHO + H₂O (Cu or Ag catalyst at 300 °C, or PCC).","(c, d) Structural formulas: i. pentan-2-ol: CH₃–CH(OH)–CH₂CH₂CH₃. ii. 3,4-dimethylhexan-2-ol: CH₃–CH(OH)–CH(CH₃)–CH(CH₃)–CH₂CH₃. iii. 4-methylpent-3-en-2-ol: CH₃–CH(OH)–CH=C(CH₃)₂.","iv. 3,4-dimethyl-2-nitrophenol: a benzene ring with –OH at C1, –NO₂ at C2 and –CH₃ at C3 and C4. v. 2,3-dimethoxy-4-methylpentane: CH₃–CH(OCH₃)–CH(OCH₃)–CH(CH₃)–CH₃. (Part (c) prints no structures to be named, so only part (d) can be answered.)"]}]}},"19":{"items":{"mcqs":[{"q":[["19.11",2],["19.11",3]],"s":["The carbonyl carbon forms three σ bonds (two to C/H, one to O) and one π bond to oxygen.","It is sp²-hybridised and trigonal planar (≈ 120°)."],"inline":1,"c":1},{"q":[["19.11",4],["19.11",5]],"s":["Clemmensen reduction (Zn–Hg amalgam + concentrated HCl) converts >C=O directly into >CH₂.","Catalytic reduction and metal hydrides give alcohols instead."],"inline":1,"c":2},{"q":[["19.11",6],["19.11",7]],"s":["HCHO + CH₃MgI → CH₃CH₂OMgI; hydrolysis gives CH₃CH₂OH.","Formaldehyde with a Grignard reagent gives a primary alcohol — here ethyl alcohol."],"inline":1,"c":3},{"q":[["19.11",8],["19.11",9]],"s":["Tollens' reagent (ammoniacal AgNO₃) is reduced to a silver mirror only by aldehydes.","Ethanal CH₃CHO is an aldehyde; acetone, ethanol and dimethyl ether do not react."],"inline":1,"c":3},{"q":[["19.11",10],["19.11",11]],"s":["Fehling's solution is reduced by aliphatic aldehydes, giving a red precipitate of copper(I) oxide.","Of the choices, only C₂H₅CHO (propanal) is an aldehyde; it has no –OH group, so it does not react with sodium. The alcohols react with Na; acetone does not reduce Fehling's."],"n":"Fehling's test gives cuprous oxide, Cu₂O (red), not cupric oxide as printed.","inline":1,"c":1},{"q":[["19.11",12],["19.11",13]],"s":["Acetone is CH₃COCH₃, a three-carbon ketone.","IUPAC name: propanone."],"inline":1,"c":1},{"q":[["19.11",14],["19.11",15]],"s":["Formalin is a 40% aqueous solution of formaldehyde (used as a preservative and disinfectant)."],"inline":1,"c":2},{"q":[["19.11",16],["19.11",17]],"s":["Ozonolysis splits C=C into two carbonyl compounds. But-2-ene CH₃CH=CHCH₃ gives two molecules of the same aldehyde, CH₃CHO.","But-1-ene and propene give two different aldehydes; 2,3-dimethylbut-2-ene gives only acetone (a ketone)."],"inline":1,"c":2},{"q":[["19.11",18],["19.11",19]],"s":["Hydration of alkynes (HgSO₄/H₂SO₄) gives ketones, except acetylene.","HC≡CH + H₂O → CH₃CHO: acetylene gives acetaldehyde, not a ketone."],"inline":1,"c":0},{"q":[["19.12",0],["19.12",1]],"s":["Water adds to the C=O of both aldehydes and ketones to form gem-diols: R₂C=O + H₂O ⇌ R₂C(OH)₂ (the equilibrium favours the diol mainly for formaldehyde and chloral)."],"inline":1,"c":3},{"q":[["19.12",2],["19.12",3]],"s":["Primary amines condense with aldehydes and ketones, losing water, to give imines (Schiff bases): R₂C=O + R′NH₂ → R₂C=NR′ + H₂O."],"inline":1,"c":0},{"q":[["19.12",4],["19.12",5]],"s":["A hemiacetal R–CH(OH)–OR′ has an –OH (alcohol) group and an –OR′ (ether) group on the same carbon."],"inline":1,"c":1},{"q":[["19.12",6],["19.12",7]],"s":["Formaldehyde HCHO has no alkyl groups: its carbonyl carbon is the most positive and least hindered.","It is the most reactive aldehyde towards nucleophilic addition."],"inline":1,"c":0},{"q":[["19.12",8],["19.12",9]],"s":["An alcohol adds to the C=O (nucleophilic addition) to give a hemiacetal, which then reacts with a second alcohol to give the acetal.","The key step is nucleophilic addition to the carbonyl group."],"inline":1,"c":3},{"q":[["19.12",10],["19.12",11]],"s":["Hydration of alkynes, oxidation of secondary alcohols and Friedel–Crafts acylation all give ketones.","Oxidation of a primary alcohol gives an aldehyde (and then a carboxylic acid), not a ketone."],"inline":1,"c":1}],"shortQuestions":[{"q":[["19.12",13]],"s":["In an aldehyde the carbonyl carbon is bonded to at least one hydrogen atom (–CHO group, at the end of a chain), e.g. CH₃CHO.","In a ketone the carbonyl carbon is bonded to two carbon groups (>C=O within the chain), e.g. CH₃COCH₃. Because of the C–H bond, aldehydes are easily oxidised (reducing agents) while ketones are not."]},{"q":[["19.12",14]],"s":["The acid protonates the carbonyl oxygen: R₂C=O + H⁺ ⇌ R₂C=OH⁺.","The positive charge is shared with the carbon (R₂C⁺–OH), so the carbonyl carbon becomes more electron-deficient (more electrophilic) and even weak nucleophiles (H₂O, ROH) can attack it."]},{"q":[["19.12",15]],"s":["The C=O bond is polar: oxygen is much more electronegative, so the carbon carries a partial positive charge and is attacked by nucleophiles; the oxygen then takes the negative charge.","The C=C bond is non-polar; its exposed π electron cloud is electron-rich and attracts electrophiles. Hence carbonyl compounds undergo nucleophilic addition and alkenes electrophilic addition."]},{"q":[["19.12",16]],"s":["An aldehyde has a hydrogen on the carbonyl carbon; this C–H bond is easily oxidised to C–OH, giving a carboxylic acid with the same number of carbons (even mild oxidants like Tollens' and Fehling's reagents do this).","A ketone has no such hydrogen; oxidation requires breaking a strong C–C bond, which needs strong oxidising agents and drastic conditions."]},{"q":[["19.12",17]],"s":["Hydration: an acid makes the carbonyl carbon more electrophilic, and a base supplies the stronger nucleophile OH⁻ — either speeds up the reaction.","Addition of HCN: the real nucleophile is CN⁻. HCN is a weak acid; a base increases [CN⁻] (HCN + OH⁻ → CN⁻ + H₂O), whereas acid suppresses its ionisation and lowers [CN⁻]. So only base catalyses cyanohydrin formation."]},{"q":[["19.12",18]],"s":["In a Grignard reagent the C–Mg bond is highly polar, so the alkyl group acts as a very strong nucleophile (a carbanion source) that attacks the carbonyl carbon directly.","At the same time Mg²⁺ acts as a Lewis acid by coordinating to the carbonyl oxygen, activating it. So no additional catalyst is needed (the reaction is done in dry ether)."]},{"q":[["19.12",19]],"s":["A ketone has two alkyl groups on the carbonyl carbon, an aldehyde only one (or none).","Electronic effect: alkyl groups donate electrons (+I), reducing the positive charge on the carbonyl carbon. Steric effect: two alkyl groups crowd the carbon and hinder the approach of the nucleophile. So ketones are less reactive than aldehydes."]},{"q":[["19.12",20]],"s":["The carbonyl oxygen has lone pairs and a partial negative charge, so it accepts hydrogen bonds from water molecules (C=O···H–O–H).","Lower aldehydes and ketones (formaldehyde, acetaldehyde, acetone) are small, so this hydrogen bonding makes them very soluble; solubility decreases as the hydrocarbon part grows."]},{"q":[["19.12",21]],"s":["Ketones are oxidised only by strong oxidants, which break a C–C bond next to the carbonyl group.","The carbon chain is split into two parts, so each carboxylic acid formed contains fewer carbon atoms than the parent ketone (e.g. CH₃COCH₂CH₃ gives CH₃COOH + CH₃COOH, or HCOOH + CH₃CH₂COOH)."]},{"q":[["19.12",22]],"s":["Tollens' test: warm the compound with Tollens' reagent (ammoniacal silver nitrate, [Ag(NH₃)₂]⁺). An aldehyde reduces Ag⁺ to metallic silver, which forms a shining silver mirror on the tube: RCHO + 2[Ag(NH₃)₂]⁺ + 3OH⁻ → RCOO⁻ + 2Ag + 4NH₃ + 2H₂O.","Ketones give no mirror. (Fehling's test: aliphatic aldehydes give a brick-red Cu₂O precipitate; ketones do not.)"]}],"longQuestions":[{"q":[["19.12",24],["19.12",25]],"s":["(a) C₅H₁₀O — aldehydes: CH₃CH₂CH₂CH₂CHO (pentanal); CH₃CH₂CH(CH₃)CHO (2-methylbutanal); (CH₃)₂CHCH₂CHO (3-methylbutanal); (CH₃)₃CCHO (2,2-dimethylpropanal).","Ketones: CH₃COCH₂CH₂CH₃ (pentan-2-one); CH₃CH₂COCH₂CH₃ (pentan-3-one); CH₃COCH(CH₃)₂ (3-methylbutan-2-one). In all, seven carbonyl isomers (2-methylbutanal is also chiral).","(b) Structure: the carbonyl carbon is sp²-hybridised; it forms three σ bonds in one plane at about 120° and a π bond with oxygen by sideways overlap of p orbitals. Oxygen is more electronegative, so the C=O bond is polar: Cδ+=Oδ−.","Reactivity: the electrophilic carbon is attacked by nucleophiles (nucleophilic addition of HCN, NaHSO₃, Grignard reagents, alcohols, ammonia derivatives); the oxygen can be protonated (acid catalysis). The polar C=O also makes α-hydrogens acidic (enolisation, aldol condensation). Aldehydes are more reactive than ketones for electronic and steric reasons."]},{"q":[["19.12",26],["19.12",27]],"s":["(a) i. Cyanohydrin: CH₃CHO + HCN —base→ CH₃CH(OH)CN. ii. Oxime: CH₃CHO + NH₂OH → CH₃CH=NOH + H₂O. iii. Imine (Schiff base): CH₃CHO + CH₃NH₂ → CH₃CH=NCH₃ + H₂O. iv. Hydrazone: (CH₃)₂C=O + NH₂NH₂ → (CH₃)₂C=NNH₂ + H₂O. v. Acetal: CH₃CHO + 2C₂H₅OH —dry HCl→ CH₃CH(OC₂H₅)₂ + H₂O.","(b) Grignard reagent + carbonyl compound, then hydrolysis (H₃O⁺): i. Butan-1-ol: CH₃CH₂CH₂MgBr + HCHO → CH₃CH₂CH₂CH₂OH. ii. Ethyl alcohol: CH₃MgI + HCHO → CH₃CH₂OH.","iii. Butan-2-ol: CH₃CH₂MgBr + CH₃CHO → CH₃CH(OH)CH₂CH₃ (or CH₃MgI + CH₃CH₂CHO). iv. 2-Methylbutan-2-ol: CH₃CH₂MgBr + CH₃COCH₃ → (CH₃)₂C(OH)CH₂CH₃."]},{"q":[["19.12",28],["19.12",29]],"s":["(a) Preparation of aldehydes: (i) controlled oxidation of primary alcohols (PCC, or K₂Cr₂O₇/H₂SO₄ with the aldehyde distilled off): CH₃CH₂OH + [O] → CH₃CHO + H₂O. (ii) Dehydrogenation of primary alcohols over copper at 300 °C: RCH₂OH → RCHO + H₂. (iii) Rosenmund reduction of acid chlorides: RCOCl + H₂ —Pd/BaSO₄→ RCHO + HCl. (Also ozonolysis of alkenes and hydration of acetylene, HC≡CH + H₂O —HgSO₄/H₂SO₄→ CH₃CHO.)","(b) i. With ethylmagnesium iodide, then hydrolysis: CH₃CHO + C₂H₅MgI → CH₃CH(OMgI)C₂H₅ → CH₃CH(OH)C₂H₅ (butan-2-ol). ii. With zinc–mercury amalgam in HCl (Clemmensen reduction): CH₃CHO + 4[H] → CH₃CH₃ + H₂O (ethane).","iii. With lithium aluminium hydride: CH₃CHO + 2[H] → CH₃CH₂OH (ethanol). iv. With acidified dichromate: CH₃CHO + [O] → CH₃COOH (acetic acid); the orange solution turns green (Cr³⁺)."]},{"q":[["19.12",30],["19.12",31]],"s":["(a) Friedel–Crafts acylation: benzene reacts with an acyl chloride in the presence of anhydrous AlCl₃: C₆H₆ + CH₃COCl → C₆H₅COCH₃ (acetophenone) + HCl. AlCl₃ forms the acylium ion: CH₃COCl + AlCl₃ → CH₃C≡O⁺ + AlCl₄⁻; the electrophile attacks the ring to give an arenium ion, which loses H⁺ (taken by AlCl₄⁻, regenerating AlCl₃). With benzoyl chloride, benzophenone C₆H₅COC₆H₅ is formed.","(b) From acetone: i. Propane — Clemmensen reduction: CH₃COCH₃ + 4[H] —Zn–Hg/HCl→ CH₃CH₂CH₃ + H₂O. ii. Propan-2-ol — reduction with NaBH₄, LiAlH₄ or H₂/Ni: CH₃COCH₃ + 2[H] → (CH₃)₂CHOH. iii. Acetone cyanohydrin — HCN with a little base: (CH₃)₂CO + HCN → (CH₃)₂C(OH)CN.","iv. Acetone hydrazone — with hydrazine: (CH₃)₂CO + NH₂NH₂ → (CH₃)₂C=NNH₂ + H₂O. v. Acetic acid — haloform reaction with NaOI (I₂/NaOH): CH₃COCH₃ + 3I₂ + 4NaOH → CH₃COONa + CHI₃ + 3NaI + 3H₂O, then acidify to CH₃COOH (or vigorous oxidation with K₂Cr₂O₇/H₂SO₄, which cleaves the molecule)."]},{"q":[["19.12",32],["19.12",33],["19.12",34],["19.13",0],["19.13",1],["19.13",2],["19.13",3]],"s":["(a) Base-catalysed nucleophilic addition: the base produces a strong nucleophile (e.g. HCN + OH⁻ → CN⁻); the nucleophile attacks the carbonyl carbon, the π electrons move to oxygen, giving a tetrahedral alkoxide ion; the alkoxide takes a proton from the solvent or HCN, giving the product (cyanohydrin) and regenerating the nucleophile. Acid-catalysed: H⁺ protonates the carbonyl oxygen, making the carbon strongly electrophilic; a weak nucleophile (H₂O, ROH) attacks the carbon; loss of H⁺ from the attacking group gives the product (hydrate, hemiacetal) and regenerates H⁺.","(b) Physical properties: formaldehyde is a gas; other lower aldehydes and ketones are liquids, higher ones solids. Their boiling points are higher than those of alkanes of similar mass (dipole–dipole attraction) but lower than those of alcohols (no intermolecular hydrogen bonding). Lower members are soluble in water (hydrogen bonding with water). Lower aldehydes have sharp, pungent smells; ketones and higher aldehydes have pleasant smells; acetone is a good solvent.","(c, d) Structural formulas: i. 2,4-dimethylpent-2-enal: OHC–C(CH₃)=CH–CH(CH₃)–CH₃. ii. 2,2-dimethylbutanal: OHC–C(CH₃)₂–CH₂CH₃. iii. 3,3-dimethylhex-4-en-2-one: CH₃CO–C(CH₃)₂–CH=CH–CH₃.","iv. 4-methylhex-5-en-3-one: CH₃CH₂CO–CH(CH₃)–CH=CH₂. v. pent-4-yn-2-one: CH₃CO–CH₂–C≡CH. (Part (c) prints no structures to be named, so only part (d) can be answered.)"]}],"activities":[{"q":[["19.13",5],["19.13",6]],"s":["Preparing Tollens' reagent: NH₄OH first precipitates brown silver oxide, 2AgNO₃ + 2NH₄OH → Ag₂O + 2NH₄NO₃ + H₂O; excess ammonia dissolves it as the diamminesilver(I) ion, Ag₂O + 4NH₃ + H₂O → 2[Ag(NH₃)₂]⁺ + 2OH⁻.","Glucose contains an aldehyde (–CHO) group, which reduces Ag⁺ to metallic silver while it is oxidised: RCHO + 2[Ag(NH₃)₂]⁺ + 3OH⁻ → RCOO⁻ + 2Ag↓ + 4NH₃ + 2H₂O. The silver deposits as a bright mirror on the clean glass.","Conclusion: aldehydes give a silver mirror; ketones (e.g. acetone) give no mirror, so the test distinguishes aldehydes from ketones. Safety: prepare the reagent fresh and wash it away after use, since on standing it can form explosive silver compounds."]}]}},"20":{"items":{"mcqs":[{"q":[["20.11",2],["20.11",3]],"s":["An aromatic carboxylic acid has –COOH attached to an aromatic ring.","C₆H₅COOH (benzoic acid). HCOOH is aliphatic; C₆H₅OH is phenol and C₆H₅CH₂OH benzyl alcohol."],"inline":1,"c":2},{"q":[["20.11",4],["20.11",5]],"s":["Rancid butter smells of butyric (butanoic) acid, CH₃CH₂CH₂COOH.","Its molecular formula is C₄H₈O₂."],"inline":1,"c":2},{"q":[["20.11",6],["20.11",7]],"s":["Acetic acid forms strong hydrogen-bonded dimers and boils at 118 °C.","Water boils at 100 °C, ethanol at 78 °C and diethyl ether at 35 °C."],"inline":1,"c":0},{"q":[["20.11",8],["20.11",9]],"s":["In methanal, methanoic acid and acetone the carbonyl carbon is sp² (it forms a C=O double bond).","In methanol CH₃OH the carbon has four single bonds, so it is sp³-hybridised."],"inline":1,"c":1},{"q":[["20.11",10],["20.11",11]],"s":["Electron-withdrawing halogens stabilise the carboxylate ion (−I effect) and increase acidity; fluorine is the most electronegative.","Fluoroacetic acid (pKa ≈ 2.6) is stronger than chloroacetic acid (2.9), acetic acid (4.8) and ethanol (≈ 16)."],"inline":1,"c":3},{"q":[["20.11",12],["20.11",13]],"s":["Nitriles are hydrolysed by dilute acid to carboxylic acids: CH₃C≡N + 2H₂O + H⁺ → CH₃COOH + NH₄⁺.","So methyl cyanide (acetonitrile) gives acetic acid."],"inline":1,"c":0},{"q":[["20.11",14],["20.11",15]],"s":["Fischer esterification: a carboxylic acid is heated with an alcohol in the presence of concentrated H₂SO₄: RCOOH + R′OH ⇌ RCOOR′ + H₂O."],"inline":1,"c":1},{"q":[["20.11",16],["20.11",17]],"s":["RCOOH + SOCl₂ → RCOCl + SO₂ + HCl.","Thionyl chloride is ideal because the by-products are gases (PCl₅ and PCl₃ also work)."],"inline":1,"c":3},{"q":[["20.11",18],["20.11",19]],"s":["Hydrolysis of an ester by an alkali gives an alcohol and the salt of the acid: RCOOR′ + NaOH → RCOONa + R′OH.","This is called saponification (soap-making from fats)."],"inline":1,"c":0},{"q":[["20.11",20],["20.11",21]],"s":["Acid halides, anhydrides, esters and amides all give back the carboxylic acid on hydrolysis (reaction with water, often with acid or base).","The common reaction is hydrolysis."],"inline":1,"c":3}],"shortQuestions":[{"q":[["20.12",1]],"s":["Pure (anhydrous) acetic acid freezes at 16.6 °C.","In cold weather it solidifies into colourless, ice-like crystals (glacies = ice), so it is called glacial acetic acid."]},{"q":[["20.12",2]],"s":["The –COOH group has a strongly polar O–H and a C=O that accepts hydrogen bonds, so two acid molecules join by two hydrogen bonds to form a cyclic dimer.","These strong double hydrogen bonds (which persist even in the vapour) need more energy to break than the single hydrogen bonds in alcohols, so carboxylic acids boil higher than alcohols of similar molecular mass (acetic acid 118 °C, propan-1-ol 97 °C)."]},{"q":[["20.12",3]],"s":["In the carboxylate ion RCOO⁻ the negative charge is shared equally between two oxygen atoms by resonance (two equivalent structures), which strongly stabilises it.","In the phenoxide ion the charge is delocalised onto ring carbons, which is less effective; in water (OH⁻) and alkoxide ions (RO⁻) there is no resonance (and alkyl groups even destabilise RO⁻).","So acid strength: RCOOH (pKa ≈ 4–5) > phenol (≈ 10) > water (15.7) > alcohols (≈ 16–18)."]},{"q":[["20.12",4]],"s":["In ethanoic acid the methyl group releases electrons (+I effect), which intensifies the negative charge on the ethanoate ion and makes the O–H bond less polar.","Methanoic acid has only H on the carboxyl carbon, so its anion is more stable and it ionises more: pKa 3.75 (methanoic) vs 4.76 (ethanoic)."]},{"q":[["20.12",5]],"s":["Chlorine is highly electronegative and withdraws electrons through the C–C bond (−I effect).","This disperses the negative charge of the chloroacetate ion (stabilising it) and makes the O–H bond more polar, so H⁺ is released more readily: pKa 2.86 compared with 4.76 for acetic acid."]},{"q":[["20.12",6]],"s":["A primary alcohol is first oxidised to an aldehyde, which is itself easily oxidised further to the carboxylic acid: RCH₂OH + [O] → RCHO + H₂O; RCHO + [O] → RCOOH.","Heating under reflux with excess strong oxidant (acidified K₂Cr₂O₇ or KMnO₄) keeps the aldehyde in the flask so that it is converted completely into the acid, e.g. CH₃CH₂OH → CH₃COOH."]},{"q":[["20.12",7]],"s":["In a carboxylic acid the lone pair on the –OH oxygen is delocalised into the C=O group by resonance (O=C–OH ↔ ⁻O–C=OH⁺), which reduces the positive charge on the carbonyl carbon.","Also, basic nucleophiles simply remove the acidic proton to form the carboxylate ion, whose negative charge repels further nucleophilic attack. So acids are less reactive than aldehydes towards nucleophiles."]},{"q":[["20.12",8]],"s":["In an amide the lone pair on nitrogen is strongly delocalised into the carbonyl group (resonance O=C–NH₂ ↔ ⁻O–C=NH₂⁺), so the carbonyl carbon is only weakly electrophilic.","In addition, NH₂⁻ is a very strong base and therefore a very poor leaving group. Hence amides are the least reactive acid derivatives."]},{"q":[["20.12",9]],"s":["Fats and oils are esters of glycerol with long-chain fatty acids. Boiling them with NaOH (or KOH) hydrolyses them to glycerol and the sodium salts of the fatty acids — which are soaps.","So alkaline hydrolysis of esters is called saponification (Latin sapo = soap). It goes to completion because the carboxylate ion formed does not react back with the alcohol."]},{"q":[["20.12",10]],"s":["Chlorine is strongly electronegative, so it withdraws electrons and makes the carbonyl carbon highly electrophilic; its lone pairs donate very little back by resonance (poor overlap of Cl 3p with C 2p).","Cl⁻ is a very weak base and therefore an excellent leaving group. So acid halides react fastest: acid halides > anhydrides > esters > amides."]}],"longQuestions":[{"q":[["20.12",12]],"s":["Carboxylic acids are weak acids: RCOOH + H₂O ⇌ RCOO⁻ + H₃O⁺ (Ka ≈ 10⁻⁵, e.g. acetic acid pKa 4.76). Their acidity comes from the polar O–H bond and especially from resonance stabilisation of the carboxylate ion, whose negative charge is spread equally over two oxygen atoms (both C–O bonds 127 pm).","They turn blue litmus red, react with metals (H₂), bases and even NaHCO₃ (liberating CO₂), so they are stronger than phenols and alcohols.","Electron-withdrawing substituents (–F, –Cl, –Br, –NO₂, –CN) increase acid strength by the −I effect, dispersing the negative charge: CH₃COOH (4.76) < ClCH₂COOH (2.86) < Cl₂CHCOOH (1.29) < Cl₃CCOOH (0.65); FCH₂COOH > ClCH₂COOH > BrCH₂COOH > ICH₂COOH. The effect weakens with distance (2-chlorobutanoic > 3-chlorobutanoic > 4-chlorobutanoic).","Electron-donating (alkyl) groups decrease acid strength (+I effect): HCOOH (3.75) > CH₃COOH (4.76) > CH₃CH₂COOH (4.87). In benzoic acids, p-nitrobenzoic acid is stronger and p-methylbenzoic acid weaker than benzoic acid (4.2)."]},{"q":[["20.12",13],["20.12",14]],"s":["i. From a nitrile (acid hydrolysis): CH₃C≡N + 2H₂O —H⁺→ CH₃COOH + NH₄⁺.","ii. From a Grignard reagent and CO₂, then hydrolysis: CH₃MgBr + CO₂ → CH₃COOMgBr —H₃O⁺→ CH₃COOH + Mg(OH)Br.","iii. From an alcohol (oxidation): CH₃CH₂OH + 2[O] —K₂Cr₂O₇/H₂SO₄, reflux→ CH₃COOH + H₂O.","iv. From an aldehyde (oxidation): CH₃CHO + [O] —K₂Cr₂O₇/H₂SO₄→ CH₃COOH.","v. From an acid halide (hydrolysis): CH₃COCl + H₂O → CH₃COOH + HCl."]},{"q":[["20.12",15],["20.12",16]],"s":["i. Acetyl chloride: CH₃COOH + SOCl₂ → CH₃COCl + SO₂ + HCl (or 3CH₃COOH + PCl₃ → 3CH₃COCl + H₃PO₃).","ii. Acetic anhydride: heat acetic acid with P₂O₅: 2CH₃COOH → (CH₃CO)₂O + H₂O; or CH₃COCl + CH₃COONa → (CH₃CO)₂O + NaCl.","iii. Acetamide: CH₃COOH + NH₃ → CH₃COONH₄, then heat: CH₃COONH₄ → CH₃CONH₂ + H₂O.","iv. Ethyl acetate: CH₃COOH + C₂H₅OH ⇌ (conc. H₂SO₄) CH₃COOC₂H₅ + H₂O.","v. Ethyl alcohol: reduction with lithium aluminium hydride: CH₃COOH + 4[H] —LiAlH₄→ CH₃CH₂OH + H₂O."]},{"q":[["20.12",17],["20.12",18]],"s":["i. Hydrolysis of acetyl chloride: CH₃COCl + H₂O → CH₃COOH + HCl.","ii. Benzoyl chloride with methanol: C₆H₅COCl + CH₃OH → C₆H₅COOCH₃ (methyl benzoate) + HCl.","iii. Butan-1-ol with acetic anhydride: CH₃CH₂CH₂CH₂OH + (CH₃CO)₂O → CH₃COOCH₂CH₂CH₂CH₃ (butyl acetate) + CH₃COOH.","iv. Ammonolysis of butanoyl chloride: CH₃CH₂CH₂COCl + 2NH₃ → CH₃CH₂CH₂CONH₂ (butanamide) + NH₄Cl.","v. Fischer esterification of pentanoic acid with ethanol: CH₃(CH₂)₃COOH + C₂H₅OH ⇌ (conc. H₂SO₄) CH₃(CH₂)₃COOC₂H₅ (ethyl pentanoate) + H₂O."]},{"q":[["20.12",19],["20.12",20],["20.12",21],["20.12",22],["20.12",23],["20.12",24],["20.12",25],["20.12",26],["20.12",27],["20.12",28],["20.12",29],["20.12",30],["20.12",31]],"s":["(a) Preparation of carboxylic acids: (i) oxidation of primary alcohols or aldehydes with acidified K₂Cr₂O₇ or KMnO₄: RCH₂OH → RCOOH; (ii) hydrolysis of nitriles: RC≡N + 2H₂O + H⁺ → RCOOH + NH₄⁺; (iii) carbonation of Grignard reagents: RMgX + CO₂ → RCOOMgX → (H₃O⁺) RCOOH. (Also oxidation of alkylbenzenes: C₆H₅CH₃ + 3[O] —KMnO₄→ C₆H₅COOH + H₂O.)","(b, c) Structural formulas: i. 3-ethyl-4-methylpentanoic acid: HOOC–CH₂–CH(C₂H₅)–CH(CH₃)–CH₃. ii. Ethyl 3-methylbutanoate: (CH₃)₂CH–CH₂–COO–C₂H₅. iii. 2-Chloropropanoyl bromide: CH₃–CHCl–COBr. iv. Ethanoic propanoic anhydride: CH₃CO–O–COCH₂CH₃. v. 3,3-Dimethylbutanenitrile: (CH₃)₃C–CH₂–C≡N. (Part (b) prints no structures to be named.)","(d) i. CH₃CH₂CH₂COOH + PCl₅ → CH₃CH₂CH₂COCl + POCl₃ + HCl. ii. CH₃CH₂COOH + SOCl₂ → CH₃CH₂COCl + SO₂ + HCl. iii. CH₃CH₂CONH₂ + 4[H] (LiAlH₄) → CH₃CH₂CH₂NH₂ + H₂O. iv. CH₃COOCOCH₃ + NH₃ → CH₃CONH₂ + CH₃COOH (with excess NH₃ the acid becomes CH₃COONH₄).","v. CH₃CH₂COOCH₃ + NaOH → CH₃CH₂COONa + CH₃OH. vi. CH₃CH₂COONa + NaOH —CaO, heat→ CH₃CH₃ + Na₂CO₃ (decarboxylation). vii. CH₃CH₂COOC₂H₅ + 4[H] (LiAlH₄) → CH₃CH₂CH₂OH + C₂H₅OH. viii. CH₃CH₂MgBr + CH₃CH₂C≡N → (CH₃CH₂)₂C=NMgBr, which on hydrolysis (H₃O⁺) gives CH₃CH₂COCH₂CH₃ (pentan-3-one) + NH₃ + Mg(OH)Br."]}],"activities":[{"q":[["20.12",33]],"s":["Observation: brisk effervescence (bubbles of gas) as soon as the acid is added to sodium hydrogencarbonate solution; the gas turns lime water milky, showing it is CO₂.","Equation: RCOOH + NaHCO₃ → RCOONa + H₂O + CO₂↑ (e.g. CH₃COOH + NaHCO₃ → CH₃COONa + H₂O + CO₂).","Carboxylic acids are stronger acids than carbonic acid, so they liberate CO₂; phenols and alcohols are weaker and give no bubbles. This test distinguishes carboxylic acids from them."]}]}},"21":{"items":{"mcqs":[{"q":[["21.19",11],["21.19",12]],"s":["Pepsin works in the strongly acidic gastric juice of the stomach.","Its optimum pH is about 2.0 (≈ 1.5–2)."],"inline":1,"c":2},{"q":[["21.19",13],["21.19",14]],"s":["Cellulose forms the cell walls of all plants, so it is the most abundant carbohydrate (and organic compound) in nature."],"inline":1,"c":0},{"q":[["21.19",15],["21.19",16]],"s":["A glycosidic linkage (C–O–C) joins monosaccharide units, e.g. two glucose molecules in maltose or many in starch.","Glycine is an amino acid (peptide bonds) and fatty acids form ester bonds."],"inline":1,"c":0},{"q":[["21.19",17],["21.19",18]],"s":["Steroids (cholesterol, sex hormones, cortisol) are insoluble in water and soluble in organic solvents.","They are classed as (derived) lipids."],"inline":1,"c":2},{"q":[["21.19",19],["21.19",20]],"s":["Haemoglobin consists of four polypeptide chains (two α and two β) held together.","The association of several chains is the quaternary structure."],"inline":1,"c":3},{"q":[["21.19",21],["21.19",22]],"s":["Glucose and fructose are C₆H₁₂O₆ = C₆(H₂O)₆; ribose is C₅H₁₀O₅ = C₅(H₂O)₅.","Deoxyribose C₅H₁₀O₄ has one oxygen fewer, so it does not fit Cₙ(H₂O)ₙ."],"inline":1,"c":0},{"q":[["21.19",23],["21.19",24]],"s":["Starch is hydrolysed to glucose, which yeast (zymase) converts into ethanol: C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂.","The process is fermentation."],"inline":1,"c":3},{"q":[["21.19",25],["21.19",26]],"s":["Humans lack the enzyme cellulase needed to break the β-1,4-glycosidic bonds of cellulose.","So cellulose (dietary fibre) cannot be digested."],"inline":1,"c":1},{"q":[["21.19",27],["21.19",28]],"s":["An aldohexose is a sugar with an aldehyde group and six carbon atoms (e.g. glucose).","'Ketone' does not belong — a ketone sugar would be a ketose."],"inline":1,"c":1},{"q":[["21.19",29],["21.19",30]],"s":["Zinc is a cofactor of many enzymes needed for protein synthesis, cell division and tissue repair.","Zinc deficiency causes slow healing of wounds."],"inline":1,"c":2},{"q":[["21.19",31],["21.19",32]],"s":["DNA is found mainly in the nucleus; RNA is made there but is found mainly in the cytoplasm (ribosomes, mRNA, tRNA), where proteins are synthesised."],"inline":1,"c":1},{"q":[["21.19",33],["21.19",34]],"s":["Maltose = glucose + glucose; lactose = glucose + galactose; sucrose = glucose + fructose.","Only maltose has two identical units."],"inline":1,"c":0},{"q":[["21.19",35],["21.19",36]],"s":["A competitive inhibitor resembles the substrate and binds to the active site.","It competes with the substrate (its effect can be overcome by raising the substrate concentration)."],"inline":1,"c":3},{"q":[["21.19",37],["21.19",38]],"s":["In DNA, adenine pairs with thymine by two hydrogen bonds (A=T); guanine pairs with cytosine by three (G≡C).","Uracil replaces thymine only in RNA."],"inline":1,"c":2},{"q":[["21.19",39],["21.19",40]],"s":["Proteins are polymers (polypeptides) of α-amino acids joined by peptide bonds."],"inline":1,"c":2}],"shortQuestions":[{"q":[["21.20",1]],"s":["Vegetable oils contain a high proportion of unsaturated fatty acids with C=C double bonds.","Oxygen of the air attacks these double bonds (oxidative rancidity), forming peroxides that break down into aldehydes and ketones with unpleasant smells and tastes; moisture, light, heat and microbes also hydrolyse the oil into free fatty acids (hydrolytic rancidity).","So oils go rancid faster than saturated fats; antioxidants and airtight storage slow it down."]},{"q":[["21.20",2]],"s":["Saturated fatty acids have straight hydrocarbon chains that pack closely together, giving strong van der Waals forces between molecules — so more energy is needed to melt them (e.g. stearic acid m.p. 70 °C).","Cis double bonds in unsaturated fatty acids put kinks in the chains, so they pack loosely with weaker forces and melt at lower temperatures (oleic acid m.p. 13 °C)."]},{"q":[["21.20",3]],"s":["(a) Glucose is an aldohexose (–CHO group; usually a six-membered pyranose ring) and is dextrorotatory; fructose is a ketohexose (C=O at C2; five-membered furanose ring in sucrose) and is laevorotatory.","(b) Sucrose is glucose + fructose joined α1→β2 through both anomeric carbons, so it is non-reducing; maltose is glucose + glucose joined α1→4, so it is a reducing sugar.","(c) Cellulose is a linear polymer of β-glucose (β-1,4 links), a structural polysaccharide that humans cannot digest and that gives no colour with iodine; starch is a polymer of α-glucose (amylose α-1,4 and branched amylopectin α-1,6), a storage food that humans digest and that gives a blue-black colour with iodine."]},{"q":[["21.20",4]],"s":["DNA stores the genetic (hereditary) information of the cell in the sequence of its bases.","DNA replicates and passes the genetic information from parent cells to daughter cells (heredity).","RNA (mRNA, tRNA, rRNA) carries out protein synthesis by transcribing and translating the genetic code, thus controlling all cell activities. (Nucleotides such as ATP also act as energy carriers and coenzymes.)"]},{"q":[["21.20",5]],"s":["Sucrose is hydrolysed by dilute acid or the enzyme invertase (sucrase):","C₁₂H₂₂O₁₁ + H₂O → C₆H₁₂O₆ (glucose) + C₆H₁₂O₆ (fructose).","The equimolar mixture is called invert sugar because the sign of optical rotation changes from + (sucrose) to − (fructose is strongly laevorotatory)."]},{"q":[["21.20",6]],"s":["Denaturation destroys the secondary, tertiary and quaternary structure of a protein: hydrogen bonds, ionic bonds, disulphide links and hydrophobic interactions are broken by heat, strong acids/bases, heavy-metal ions, alcohol, radiation or shaking.","The primary structure (peptide bonds) remains, but the protein unfolds, loses its biological activity (enzymes stop working), becomes less soluble and often coagulates — e.g. boiled egg white or curdled milk. It is usually irreversible."]},{"q":[["21.20",7]],"s":["Nucleic acids are polymers of nucleotides. Each nucleotide has three components:","(1) a pentose sugar — deoxyribose in DNA, ribose in RNA; (2) a phosphate group; (3) a nitrogenous base — purines adenine (A) and guanine (G), pyrimidines cytosine (C) and thymine (T, in DNA) or uracil (U, in RNA).","Nucleotides are joined by 3′–5′ phosphodiester bonds forming the sugar–phosphate backbone."]},{"q":[["21.20",8]],"s":["Primary: the sequence of amino acids in the polypeptide chain, joined by peptide bonds.","Secondary: regular folding of the chain into an α-helix or β-pleated sheet, held by hydrogen bonds between the C=O and N–H groups of the backbone.","Tertiary: the overall three-dimensional folding of the whole chain, held by interactions between side chains (hydrogen bonds, ionic bonds, disulphide bridges, hydrophobic forces).","Quaternary: the arrangement of two or more polypeptide chains (subunits) in one functional protein, e.g. haemoglobin with four chains."]},{"q":[["21.20",9]],"s":["Non-competitive inhibition: the inhibitor binds to a site other than the active site, on either the free enzyme or the enzyme–substrate complex; it changes the enzyme's shape. Vmax decreases while Km is unchanged; adding substrate does not reverse it.","Uncompetitive inhibition: the inhibitor binds only to the enzyme–substrate (ES) complex, not to the free enzyme. Both Vmax and Km decrease."]},{"q":[["21.20",10]],"s":["Physical properties: lipids are insoluble in water but soluble in organic solvents (ether, chloroform, benzene); they are greasy, less dense than water and poor conductors of heat; fats (mostly saturated) are solid and oils (unsaturated) liquid at room temperature; pure lipids are colourless and odourless.","Chemical properties: hydrolysis by acids or lipase gives glycerol and fatty acids; saponification with NaOH gives soap and glycerol; hydrogenation of oils (Ni catalyst) gives solid fats (vanaspati ghee); addition of iodine/halogens to C=C (iodine number measures unsaturation); oxidation by air causes rancidity."]}],"longQuestions":[{"q":[["21.20",12],["21.20",13]],"s":["(a) Carbohydrates are polyhydroxy aldehydes or polyhydroxy ketones, or substances that give these on hydrolysis; most have the formula Cₓ(H₂O)ᵧ. Classification by the number of sugar units on hydrolysis: (i) Monosaccharides — cannot be hydrolysed further; classified by number of carbons (trioses, pentoses, hexoses) and functional group (aldoses, e.g. glucose, ribose; ketoses, e.g. fructose). (ii) Oligosaccharides — 2–10 units; disaccharides: sucrose, maltose, lactose. (iii) Polysaccharides — many units; starch, glycogen, cellulose, chitin. They are also classed as reducing or non-reducing, and as sugars (sweet, soluble) or non-sugars.","(b) Role in health: glucose is the main fuel of cells (essential for the brain and red blood cells); glycogen stores energy in liver and muscles; dietary fibre (cellulose) aids digestion, prevents constipation and lowers cholesterol; ribose and deoxyribose form nucleic acids; glycoproteins act in cell recognition.","Diseases: diabetes mellitus — lack of insulin or insulin resistance causes high blood glucose; excess sugar intake leads to obesity, tooth decay and heart disease; hypoglycaemia (low blood sugar) causes dizziness and fainting; lactose intolerance (lack of lactase) causes bloating and diarrhoea; galactosaemia and glycogen-storage diseases are inherited disorders."]},{"q":[["21.20",14],["21.20",15]],"s":["(a) Classification of proteins: (i) By composition — simple proteins give only amino acids on hydrolysis (albumins, globulins, histones, glutelins, scleroproteins such as keratin and collagen); conjugated proteins contain a non-protein prosthetic group (glycoproteins — mucin; lipoproteins; nucleoproteins; chromoproteins — haemoglobin; phosphoproteins — casein; metalloproteins — ferritin); derived proteins are formed by partial hydrolysis or denaturation (proteoses, peptones, peptides).","(ii) By shape — fibrous proteins: long, insoluble, structural (keratin of hair, collagen, myosin, silk fibroin); globular proteins: compact, water-soluble, functional (enzymes, insulin, haemoglobin, antibodies). (iii) By function — enzymes, hormones (insulin), transport (haemoglobin), structural (collagen), contractile (actin, myosin), defensive (antibodies), storage (casein, ovalbumin).","(b) Properties: high molecular masses and colloidal solutions; amphoteric (contain –NH₂ and –COOH), with an isoelectric point at which solubility is lowest; denatured by heat, acids, alkalis, heavy metals and alcohol; hydrolysed by acids, alkalis or enzymes into amino acids; optically active; precipitated by salts and heavy-metal ions; colour tests — biuret (violet), xanthoproteic (yellow with HNO₃), Millon's (red), ninhydrin (purple)."]},{"q":[["21.21",0],["21.21",1]],"s":["(a) Lipids are naturally occurring esters of fatty acids (and related compounds) that are insoluble in water but soluble in non-polar organic solvents. Classification: (i) Simple lipids — esters of fatty acids with alcohols: fats and oils (triglycerides of glycerol) and waxes (esters of long-chain alcohols). (ii) Compound lipids — esters containing extra groups: phospholipids (lecithin, cephalin), glycolipids, lipoproteins. (iii) Derived lipids — obtained by hydrolysis or related: fatty acids, glycerol, steroids (cholesterol, sex hormones), fat-soluble vitamins A, D, E, K.","(b) Structure: a fat or oil is a triglyceride — glycerol esterified with three fatty acids, which may be saturated (palmitic C₁₅H₃₁COOH, stearic C₁₇H₃₅COOH) or unsaturated (oleic, linoleic, linolenic). Phospholipids have one fatty acid replaced by a phosphate group, giving a polar head and two non-polar tails.","Nutritional importance: the most concentrated source of energy (about 37 kJ g⁻¹, twice that of carbohydrates); supply essential fatty acids (linoleic, linolenic) that the body cannot make; carry the fat-soluble vitamins A, D, E and K; improve taste and satiety.","Biological importance: energy storage in adipose tissue; thermal insulation and protection of organs; phospholipids and cholesterol form cell membranes; steroids act as hormones (testosterone, oestrogen, cortisol) and cholesterol forms vitamin D and bile salts; prostaglandins regulate body processes. Excess saturated fat and cholesterol contribute to obesity, atherosclerosis and heart disease."]},{"q":[["21.21",2],["21.21",3]],"s":["(a) Enzyme inhibitors are substances that reduce the rate of enzyme-catalysed reactions. Reversible inhibitors: competitive — structurally similar to the substrate, they bind to the active site and compete with it (e.g. malonate inhibits succinate dehydrogenase; sulpha drugs block bacterial folate synthesis); raising substrate concentration overcomes them. Non-competitive — bind elsewhere and change the shape of the enzyme (heavy-metal ions at low levels); uncompetitive — bind to the enzyme–substrate complex. Irreversible inhibitors bind covalently and permanently destroy the active site (nerve gases on acetylcholinesterase, cyanide on cytochrome oxidase, aspirin on cyclooxygenase, penicillin on bacterial transpeptidase).","Role: natural inhibitors regulate metabolic pathways (feedback inhibition — the end product inhibits an early enzyme); many drugs, antibiotics and pesticides act as enzyme inhibitors; some poisons kill by inhibiting vital enzymes.","(b) Structural components: both DNA and RNA are polynucleotides; each nucleotide = pentose sugar + phosphate + nitrogenous base, linked by 3′–5′ phosphodiester bonds into a sugar–phosphate backbone.","DNA: sugar deoxyribose; bases A, G, C and T; two antiparallel strands coiled into a double helix, held by hydrogen bonds between complementary bases (A=T, G≡C); found mainly in the nucleus. RNA: sugar ribose; bases A, G, C and U (uracil instead of thymine); usually single-stranded; three types — mRNA, tRNA and rRNA; found mainly in the cytoplasm."]},{"q":[["21.21",4],["21.21",5]],"s":["(a) Enzymes are protein biocatalysts. They speed up reactions (often millions of times) by providing an active site where the substrate binds (lock-and-key or induced-fit model), forming an enzyme–substrate complex that lowers the activation energy; they are highly specific, work under mild conditions (37 °C, near-neutral pH), are needed only in small amounts and are not used up.","Digestion of food: salivary amylase converts starch to maltose in the mouth; pepsin (stomach, pH ≈ 2) breaks proteins into peptides; in the small intestine pancreatic amylase, trypsin and chymotrypsin, and lipase (with bile) digest starch, proteins and fats; maltase, sucrase and lactase split disaccharides into monosaccharides; peptidases give amino acids. Thus large insoluble molecules are converted into small, soluble, absorbable ones.","(b) Temperature: the rate rises with temperature (more collisions) up to an optimum (about 37 °C for human enzymes); above it the enzyme is denatured and activity falls sharply; at low temperature enzymes are inactive but not destroyed.","pH: each enzyme works best at an optimum pH (pepsin ≈ 2, salivary amylase ≈ 6.8, trypsin ≈ 8); other pH values change the ionisation of groups in the active site and can denature the enzyme. Other factors: substrate concentration (rate rises then levels off at Vmax when the enzyme is saturated), enzyme concentration (rate proportional to it), cofactors/activators and inhibitors."]},{"q":[["21.21",6],["21.21",7]],"s":["(a) Zinc is an essential trace element: it is a cofactor of more than 300 enzymes (carbonic anhydrase, alcohol dehydrogenase, DNA and RNA polymerases); it is needed for protein synthesis, cell division and growth, wound healing, the immune system, the storage and action of insulin, sperm production, and the senses of taste and smell.","Zinc deficiency causes slow wound healing, stunted growth, loss of appetite and taste, skin problems, hair loss, poor immunity and delayed sexual development. Sources: meat, fish, eggs, nuts, whole grains and pulses.","(b) Calcium: deficiency causes rickets in children (soft, bent bones), osteomalacia and osteoporosis (weak, brittle bones) in adults, tetany and muscle cramps, poor blood clotting and weak teeth; excess can cause kidney stones and hypercalcaemia.","Phosphorus: needed with calcium for bones and teeth and for ATP, DNA and phospholipids. Deficiency (rare) leads to weak bones, rickets, muscle weakness and fatigue; excess phosphate (e.g. in kidney failure or very high soft-drink intake) upsets the calcium balance, causing bone loss and calcium deposits in soft tissues. Vitamin D and parathyroid hormone control the Ca/P balance."]}],"activities":[{"q":[["21.21",9]],"s":["On adding lemon juice or vinegar to warm milk, the milk curdles: white solid lumps (curd) separate from a clear yellowish-green liquid (whey)."]},{"q":[["21.21",10]],"s":["The milk changes from a uniform liquid (colloid) into a solid mass of curds suspended in a watery liquid — it coagulates."]},{"q":[["21.21",11]],"s":["Yes. The milk protein casein is denatured and precipitated; this is a chemical change and cannot be reversed by simply removing the acid."]},{"q":[["21.21",12]],"s":["Yes. The acid lowers the pH of milk (about 6.7) to the isoelectric point of casein (about pH 4.6). The negative charges on the casein micelles are neutralised, so they no longer repel each other and they clump together (coagulate). Warming speeds this up."]},{"q":[["21.21",13]],"s":["The products are casein (curd, which can be pressed into cottage cheese/paneer) and whey."]},{"q":[["21.21",14]],"s":["Yes. Casein is a high-quality phosphoprotein containing all the essential amino acids, together with calcium and phosphorus for bones and teeth. Whey also contains useful proteins, lactose, minerals and B vitamins."]},{"q":[["21.21",15]],"s":["Curd/casein is used to make paneer, cheese and other dairy products; casein is also used in protein supplements and infant foods, and industrially in glues, paints, paper coatings and casein plastics. Whey is used in whey-protein drinks and baked foods."]}]}},"22":{"items":{"mcqs":[{"q":[["22.13",2],["22.13",3]],"s":["Nylon-6,6 is made by condensation of hexamethylenediamine H₂N(CH₂)₆NH₂ (6 C) with adipic acid HOOC(CH₂)₄COOH (6 C), losing water."],"inline":1,"c":0},{"q":[["22.13",4],["22.13",5]],"s":["DDT is a chlorinated insecticide, not an antibiotic or antiseptic.","It is non-biodegradable: it persists in the environment and accumulates in food chains, so it is a serious pollutant."],"inline":1,"c":3},{"q":[["22.13",6],["22.13",7]],"s":["Petroleum (crude oil) is called 'black gold' because it is dark in colour and extremely valuable as a fuel and raw material."],"inline":1,"c":2},{"q":[["22.13",8],["22.13",9]],"s":["Ethylene oxide, polypropylene and cyclohexane are made from petroleum or natural gas.","Cellulose is a natural plant polymer, not a petrochemical."],"inline":1,"c":2},{"q":[["22.13",10],["22.13",11]],"s":["Multi-part adhesives (e.g. two-part epoxy) harden when the parts are mixed and react chemically (cross-linking).","They are reactive adhesives."],"inline":1,"c":0},{"q":[["22.13",12],["22.13",13]],"s":["Most nail-polish removers are mainly acetone, i.e. propanone (sometimes ethyl acetate)."],"inline":1,"c":1},{"q":[["22.13",14],["22.13",15]],"s":["Cracking breaks large hydrocarbon molecules into smaller, more useful ones (petrol-range alkanes and alkenes) by heat and/or catalysts."],"inline":1,"c":2},{"q":[["22.13",16],["22.13",17]],"s":["Rexine (artificial leather) is cloth coated with plasticised PVC (polyvinyl chloride)."],"inline":1,"c":0},{"q":[["22.13",18],["22.13",19]],"s":["Alkylbenzenes, cyclohexane and nitrobenzene are made from benzene.","Vinyl chloride (CH₂=CHCl) is made from ethylene (or acetylene), not benzene."],"inline":1,"c":3},{"q":[["22.13",20],["22.13",21]],"s":["Nylon is formed by condensation of a diamine and a dicarboxylic acid with loss of water.","PVC and polythene are addition polymers."],"inline":1,"c":2},{"q":[["22.13",22],["22.13",23]],"s":["The repeating unit contains –NH–(CH₂)₆–NH– from hexamethylenediamine and –CO–(CH₂)₄–CO– from adipic acid, joined by amide links with loss of water.","It is a condensation copolymer — nylon-6,6."],"n":"The printed repeat unit is garbled (–CONHCO–); the correct unit is –[NH–(CH₂)₆–NH–CO–(CH₂)₄–CO]ₙ–.","inline":1,"c":2},{"q":[["22.13",24],["22.13",25]],"s":["Cellulose, starch and silk are natural polymers.","Polythene is a synthetic polymer made from ethene."],"inline":1,"c":3},{"q":[["22.13",26],["22.13",27]],"s":["Hair dyes are classified by how long they last: temporary, semi-permanent, demi-permanent and permanent.","That is four groups."],"n":"Some books list only three groups (temporary, semi-permanent, permanent); the four-group classification includes demi-permanent dyes.","inline":1,"c":1},{"q":[["22.13",28],["22.13",29]],"s":["Polyurethanes, cyanoacrylates and polyimides are synthetic adhesives.","Casein glue is made from milk protein — a natural adhesive."],"inline":1,"c":0},{"q":[["22.13",30],["22.13",31]],"s":["Acrylate-based polymers are the main pressure-sensitive adhesives (tapes, labels, sticky notes), which stick on light pressure without heat, water or solvent."],"inline":1,"c":1}],"shortQuestions":[{"q":[["22.13",33]],"s":["Reactive adhesives harden by a chemical reaction (polymerisation or cross-linking) after application, e.g. two-part epoxy, polyurethane, cyanoacrylate (super glue, cured by moisture); the bond is strong and resistant to heat and solvents.","Non-reactive adhesives harden by a physical change — evaporation of solvent or water (white PVA glue, rubber cement), cooling of a melt (hot-melt glue) or simple pressure (pressure-sensitive tapes); no chemical reaction occurs."]},{"q":[["22.13",34]],"s":["Nail polish is a film of nitrocellulose and resins with plasticisers and pigments, left behind when its solvent evaporates.","The remover (acetone or ethyl acetate) is a strong solvent that dissolves these film-forming polymers again, so the film softens and can be wiped off with cotton."]},{"q":[["22.13",35]],"s":["Temporary hair dyes contain large dye molecules (or pigments) that only coat the outer surface (cuticle) of the hair; they cannot enter the hair shaft, and there is no chemical bonding with the hair.","So they are held weakly and are washed out by a single shampoo."]},{"q":[["22.13",36]],"s":["Pipes and fittings for water supply, drainage and sewage.","Insulation of electric wires and cables.","Floor tiles, wall coverings, window frames and doors.","Rexine (artificial leather), raincoats, bags, bottles, toys, and medical items such as blood bags and tubing."]},{"q":[["22.13",37]],"s":["Petrochemicals (primary or base petrochemicals) are the basic chemicals obtained directly from petroleum and natural gas by refining and cracking: ethylene, propylene, butadiene, benzene, toluene, xylene, methanol, synthesis gas.","Chemicals derived from them are the end products made by further reactions of these base chemicals: plastics (polythene, PVC, polystyrene), synthetic fibres (nylon, polyester), synthetic rubber, detergents, solvents, paints, fertilisers, pesticides and drugs."]},{"q":[["22.13",38]],"s":["Addition polymers are formed when unsaturated monomers (C=C) add to one another without losing any atoms; the polymer has the same empirical formula as the monomer, e.g. polythene, PVC, polystyrene (chain-growth).","Condensation polymers are formed when monomers with two functional groups join with the loss of a small molecule such as H₂O or HCl; the repeat unit differs from the monomers, e.g. nylon-6,6, polyesters (terylene), bakelite (step-growth)."]},{"q":[["22.13",39]],"s":["Acetone is a very strong solvent: it removes the natural oils of nails and skin, leaving them dry, brittle and cracked; it has a strong smell, is highly flammable and can damage artificial nails and some surfaces.","Non-acetone removers (based on ethyl acetate, propylene carbonate, etc.) are gentler and less drying, so they are better for regular use and for artificial nails — although they work more slowly on dark or glitter polish."]},{"q":[["22.13",40]],"s":["Chemical and process industries handle toxic, flammable, explosive and corrosive substances, often at high temperatures and pressures; accidents (fires, explosions, gas leaks such as Bhopal) can kill or injure workers and nearby people and damage the environment.","Safety measures — training, protective equipment, ventilation, safe design, maintenance, emergency plans — protect workers' lives and health, prevent loss of property and production, and are required by law. A safe workplace also improves morale and productivity."]},{"q":[["22.13",41]],"s":["The main goal of petroleum refining is to separate crude oil into useful fractions (by fractional distillation) and convert them (by cracking, reforming and other processes) into high-value products.","These are fuels (LPG, petrol, kerosene, diesel, fuel oil), lubricants, wax and bitumen, and feedstock for petrochemicals; impurities such as sulphur are also removed."]}],"longQuestions":[{"q":[["22.13",43],["22.13",44]],"s":["(a) Petrochemical process technology converts petroleum and natural gas into basic chemicals and then into finished products. Steps: (i) refining — crude oil is desalted and separated by fractional distillation into fractions such as naphtha and gas oil; (ii) conversion — steam cracking of ethane or naphtha gives olefins (ethylene, propylene, butadiene); catalytic reforming of naphtha gives aromatics (benzene, toluene, xylenes — BTX); steam reforming of natural gas gives synthesis gas (CO + H₂) for methanol and ammonia; (iii) further processes — polymerisation, oxidation, alkylation, chlorination, etc. — turn these into plastics, fibres, rubber, detergents, solvents and fertilisers.","(b) Cracking breaks large, less useful hydrocarbons into smaller ones (petrol-range alkanes and alkenes), e.g. C₁₆H₃₄ → C₈H₁₈ + C₈H₁₆.","Thermal cracking: heating at about 450–750 °C under pressure without catalyst; free-radical mechanism; gives many alkenes.","Catalytic cracking: about 450–550 °C at low pressure over zeolite or silica–alumina catalysts (fluid catalytic cracking); carbocation mechanism; gives branched alkanes and aromatics — high-octane petrol.","Steam cracking: hydrocarbons mixed with steam heated to about 850 °C for a very short time; main source of ethylene and propylene. Hydrocracking: cracking with hydrogen under high pressure over a catalyst; gives saturated products such as diesel and jet fuel, and removes sulphur."]},{"q":[["22.13",45],["22.13",46]],"s":["(a) Lipstick consists of waxes (beeswax, carnauba, candelilla) for shape and firmness, oils (castor oil, mineral oil, lanolin) for gloss and easy spreading, emollients, pigments and dyes (iron oxides, titanium dioxide, eosin/bromo acids, lakes) for colour, plus antioxidants, preservatives, perfume and flavour.","Preparation: the waxes and oils are melted together (about 80 °C); the pigments are ground finely in part of the oil (roller mill) and blended into the melt; perfume is added; the hot mixture is poured into metal moulds and cooled; the sticks are removed, passed briefly through a flame to give a glossy surface, and fixed in their cases.","Applications: colouring and beautifying the lips, moisturising and protecting them from drying and cracking; some contain sunscreens (SPF) or medicinal agents (lip balms).","(b) Nail polish composition: film former — nitrocellulose (forms a hard, glossy film); resins — e.g. tosylamide–formaldehyde resin for adhesion and gloss; plasticisers — camphor, dibutyl phthalate or citrates for flexibility; solvents — ethyl acetate, butyl acetate, isopropyl alcohol (dissolve the components and evaporate quickly); pigments — iron oxides, titanium dioxide, mica or guanine for pearl effects; thickening/suspending agents (stearalkonium hectorite) and UV stabilisers."]},{"q":[["22.14",0],["22.14",1]],"s":["(a) Adhesives are substances that hold two surfaces together by adhesion (attraction to the surfaces) and cohesion (internal strength).","By origin: natural adhesives — from animals or plants: animal glue (bones, hides), casein glue (milk), starch and dextrin pastes, natural rubber; synthetic adhesives — epoxies, polyvinyl acetate (white glue), polyurethanes, cyanoacrylates, polyimides, acrylics.","By reactiveness: non-reactive adhesives harden physically — drying (solvent/water based), contact, hot-melt and pressure-sensitive adhesives; reactive adhesives harden chemically — one-part (cyanoacrylates, moisture- or heat-cured) and multi-part (two-part epoxies, polyurethanes) that react when mixed.","(b) Importance: furniture and woodwork (plywood, laminates); building and construction (tiles, panels, sealants); packaging (cartons, labels, envelopes, tapes); automobile and aircraft manufacture (light, strong joints instead of rivets); electronics; shoes and leather goods; bookbinding and stationery; medicine (bandages, surgical glues, dentures); and everyday household repairs."]},{"q":[["22.14",2],["22.14",3]],"s":["(a) Raw materials in Pakistan: natural gas (Sui and other fields) — fertilisers (ammonia, urea), methanol, power; crude oil (Potwar region, Sindh) — refineries and petrochemicals; coal (Thar, Lakhra, Salt Range) — power and coke; rock salt (Khewra) — caustic soda, chlorine, soda ash; limestone, clay and gypsum — cement and lime; rock phosphate (Hazara) — phosphatic fertilisers; sulphur — sulphuric acid; sugarcane and molasses — sugar and ethanol; cotton — textiles; wood, bagasse and wheat straw — paper; chromite, iron ore and other minerals — metallurgical and chemical industries.","(b) Safety considerations in process industries: (i) hazard identification and risk assessment of chemicals, temperatures and pressures; (ii) safe plant design with relief valves, interlocks, alarms and automatic shut-down; (iii) safe storage and handling of flammable, toxic and corrosive materials with proper labelling and Material Safety Data Sheets; (iv) personal protective equipment — goggles, gloves, helmets, masks, safety shoes; (v) fire prevention, detectors and fire-fighting equipment; (vi) ventilation and gas monitoring; (vii) training, safe work procedures and permits; (viii) regular inspection and maintenance; (ix) emergency plans, drills, first aid and medical care; (x) proper waste treatment and pollution control, following national safety and environmental laws."]},{"q":[["22.14",4],["22.14",5]],"s":["(a) Fractional distillation of petroleum: crude oil is heated in a furnace to about 400 °C and the vapour enters the bottom of a tall fractionating column, which is hot at the bottom and cooler at the top. Vapours rise through trays; each component condenses at the level where the temperature equals its boiling point and is drawn off.","Fractions (from top to bottom): refinery gas (C₁–C₄; LPG, fuel and feedstock); petrol/gasoline (C₅–C₁₀; motor fuel); naphtha (C₆–C₁₀; petrochemical feedstock); kerosene (C₁₀–C₁₆; jet fuel, lamps, stoves); diesel/gas oil (C₁₄–C₂₀; diesel engines); lubricating oil (C₂₀–C₃₀); fuel oil (ships, power stations); paraffin wax; residue — bitumen/asphalt (roads, roofing).","(b) Importance of chemical industries to Pakistan's economy: fertilisers raise agricultural production and food security; cement supports construction and infrastructure; textile chemicals and dyes serve the largest export sector; pharmaceuticals, soaps, detergents, paints, plastics, paper, glass, sugar and ethanol meet daily needs.","They provide employment to many people, use local raw materials (gas, salt, limestone, coal), reduce imports and save foreign exchange, earn export income, pay taxes and contribute significantly to GDP and industrial growth."]}],"activities":[{"q":[["22.14",7]],"s":["Sample newspaper article — 'Petrochemicals: the hidden ingredients of modern life'. Crude oil and natural gas are not only fuels; they are the starting point of thousands of everyday products. After crude oil is refined into fractions, parts such as naphtha and natural gas are cracked and reformed into basic petrochemicals — ethylene, propylene, butadiene, benzene, toluene, xylene and methanol. These are turned into plastics, synthetic fibres, rubber, detergents, fertilisers, medicines and paints. From the shirt we wear to the phone we hold, petrochemicals are everywhere — which is why using them wisely and recycling plastics is so important. (The article answers the questions below.)"]},{"q":[["22.14",8]],"s":["Petroleum was formed from the remains of tiny marine plants and animals (plankton) that died millions of years ago and were buried in mud and sand on the sea floor.","Under high temperature and pressure, without oxygen, this organic matter slowly changed into hydrocarbons, which moved into porous rocks (sandstone, limestone) and were trapped beneath impervious rock layers, forming oil and gas reservoirs."]},{"q":[["22.14",9]],"s":["Crude oil is first desalted and then heated to about 400 °C and separated by fractional distillation in a tall column into fractions according to boiling point.","Fractions: refinery gas (LPG), petrol, naphtha, kerosene, diesel, lubricating oil, fuel oil, paraffin wax and bitumen. Heavy fractions are then cracked and reformed to give more petrol and alkenes, and impurities such as sulphur are removed."]},{"q":[["22.14",10]],"s":["Petrochemicals are produced mainly by: steam cracking of ethane, propane or naphtha, giving ethylene, propylene and butadiene; catalytic reforming of naphtha, giving benzene, toluene and xylenes; steam reforming of natural gas, giving synthesis gas (CO + H₂) for methanol and ammonia.","These basic chemicals are then polymerised, oxidised, chlorinated, etc. to make plastics, fibres and other chemicals."]},{"q":[["22.14",11]],"s":["Famous petrochemicals: ethylene, propylene, butadiene, benzene, toluene, xylene, methanol, styrene, vinyl chloride, ethylene oxide/ethylene glycol and acetone; and products from them such as polythene, PVC, polystyrene, nylon, polyester and synthetic rubber."]},{"q":[["22.14",12]],"s":["Petrochemicals serve as raw materials for plastics and packaging, synthetic fibres and textiles, synthetic rubber and tyres, detergents and soaps, solvents, paints and adhesives, fertilisers and pesticides, medicines and cosmetics, explosives and dyes."]},{"q":[["22.14",13]],"s":["Almost every modern product contains petrochemicals — clothing, packaging, medical equipment, car parts, electronics, building materials and household goods — so modern life depends on them.","They create jobs and industries and support agriculture (fertilisers) and health (medicines). At the same time they come from non-renewable resources and plastics cause pollution, so they must be used responsibly and recycled."]}]}},"23":{"items":{"mcqs":[{"q":[["23.11",2],["23.11",3]],"s":["Secondary pollutants are formed in the atmosphere by reactions of primary pollutants: O₃ (photochemical), H₂SO₄ (from SO₂) and H₂CO₃ (CO₂ dissolving in water).","CO₂ is emitted directly from combustion, so it is a primary pollutant."],"inline":1,"c":3},{"q":[["23.11",4],["23.11",5]],"s":["Temperature falls through the mesosphere (≈ 50–85 km) to about −92 °C at its top.","The mesosphere is the coldest region of the atmosphere."],"inline":1,"c":3},{"q":[["23.11",6],["23.11",7]],"s":["In the stratosphere UV light releases chlorine atoms from CFCs; each Cl atom destroys thousands of O₃ molecules (Cl + O₃ → ClO + O₂).","So chlorofluorocarbons are destroying the ozone layer."],"inline":1,"c":0},{"q":[["23.11",8],["23.11",9]],"s":["Sewage contains a lot of organic matter that micro-organisms decompose using dissolved oxygen.","So drained sewage has a much higher BOD than ordinary (clean) water."],"inline":1,"c":0},{"q":[["23.11",10],["23.11",11]],"s":["Photochemical smog forms when nitrogen oxides (mainly NO₂) and hydrocarbons react in sunlight: NO₂ + hν → NO + O; O + O₂ → O₃, then O₃ and PAN form.","NO₂ is the primary cause; O₃ is a product."],"inline":1,"c":3},{"q":[["23.11",12],["23.11",13]],"s":["The ozone layer absorbs harmful ultraviolet radiation.","An ozone hole lets more UV reach the Earth's surface."],"inline":1,"c":3},{"q":[["23.11",14],["23.11",15]],"s":["Acid rain contains H₂SO₄ and H₂SO₃ (from SO₂) and HNO₃ (from NOₓ).","Acetic acid CH₃COOH is not a component of acid rain."],"inline":1,"c":3},{"q":[["23.11",16],["23.11",17]],"s":["PAN (peroxyacetyl nitrate) forms when nitrogen oxides react with hydrocarbons in the presence of sunlight (photochemical smog)."],"inline":1,"c":0},{"q":[["23.11",18],["23.11",19]],"s":["Wood is mainly cellulose (C, H, O). Burning: (C₆H₁₀O₅)ₙ + 6nO₂ → 6nCO₂ + 5nH₂O.","The main gases are carbon dioxide and steam (water vapour)."],"inline":1,"c":2},{"q":[["23.11",20],["23.11",21]],"s":["In the troposphere temperature falls with height from about 15 °C at the surface to about −56 °C at the tropopause."],"inline":1,"c":0},{"q":[["23.12",0],["23.12",1]],"s":["Most of the atmosphere's ozone (the ozone layer) lies in the stratosphere, about 15–35 km above the Earth."],"inline":1,"c":1},{"q":[["23.12",2],["23.12",3]],"s":["CFCs are very stable, reach the stratosphere and release Cl atoms that catalytically destroy ozone.","They are the most dangerous for the ozone layer (oxides of nitrogen also contribute, but far less)."],"inline":1,"c":0},{"q":[["23.12",4],["23.12",5]],"s":["Dissolved oxygen (DO), biochemical oxygen demand (BOD) and chemical oxygen demand (COD) are all used to measure water quality.","All of the above."],"inline":1,"c":3},{"q":[["23.12",6],["23.12",7]],"s":["Alum (potassium aluminium sulphate) forms gelatinous Al(OH)₃, which coagulates fine suspended particles into larger flocs that settle.","It is the usual flocculating agent."],"inline":1,"c":0},{"q":[["23.12",8],["23.12",9]],"s":["Green chemistry aims to prevent waste, maximise atom economy and design less hazardous chemicals and syntheses (among its twelve principles).","All of the above."],"inline":1,"c":3}],"shortQuestions":[{"q":[["23.12",11]],"s":["Many historical monuments are made of marble or limestone (calcium carbonate). Acids in acid rain react with it: CaCO₃ + H₂SO₄ → CaSO₄ + H₂O + CO₂.","The stone slowly dissolves and crumbles ('stone cancer'), surfaces become pitted and discoloured, carvings lose their detail (e.g. the Taj Mahal), and metal parts corrode. This damage is permanent."]},{"q":[["23.12",12]],"s":["(a) Contaminant: a substance that is not normally present in the environment (or is present in larger than natural amounts); it may or may not be harmful.","(b) Pollutant: a contaminant present in amounts that cause harmful effects to living organisms, materials or the environment.","(c) Acid rain: rain (or snow, fog) with pH less than 5.6, caused by dissolved oxides of sulphur and nitrogen forming H₂SO₄ and HNO₃.","(d) Biochemical oxygen demand (BOD): the amount of dissolved oxygen (mg L⁻¹) needed by micro-organisms to decompose the organic matter in a water sample over 5 days at 20 °C; a high BOD indicates heavy organic pollution.","(e) Smog: a mixture of smoke and fog — polluted air; classical smog contains SO₂, soot and fog, while photochemical smog contains NOₓ, hydrocarbons, O₃ and PAN formed in sunlight."]},{"q":[["23.12",13]],"s":["Dissolved oxygen is essential for fish and other aquatic animals and plants to respire (most fish need more than about 5 ppm).","It allows aerobic bacteria to decompose organic matter, so water purifies itself. Clean water has about 8–10 ppm DO; low DO shows organic pollution and leads to bad smells and the death of aquatic life."]},{"q":[["23.12",14]],"s":["Use low-sulphur fuels (or remove sulphur from fuels and natural gas before burning).","Remove SO₂ from flue gases by scrubbing with lime or limestone: CaCO₃ + SO₂ → CaSO₃ + CO₂; 2CaSO₃ + O₂ → 2CaSO₄ (gypsum).","Burn less coal and oil — use natural gas, hydro, solar and wind energy; improve efficiency; recover sulphur in industries (e.g. as H₂SO₄)."]},{"q":[["23.12",15]],"s":["Prevention: it is better to prevent waste than to treat or clean it up afterwards.","Atom economy: design syntheses so that as many atoms of the reactants as possible end up in the product.","Less hazardous chemical syntheses and safer solvents: use and produce substances of little or no toxicity; use water or other safe solvents.","Use catalysts, renewable raw materials and energy-efficient (room temperature and pressure) processes; design products that degrade harmlessly after use."]},{"q":[["23.12",16]],"s":["Carbon dioxide (CO₂), methane (CH₄), nitrous oxide (N₂O) and chlorofluorocarbons (CFCs).","(Water vapour and tropospheric ozone are also greenhouse gases.)"]},{"q":[["23.12",17]],"s":["Molecule for molecule, CFCs have a far higher global-warming potential (thousands of times that of CO₂): they absorb infrared radiation strongly in the 'atmospheric window' (8–12 μm) where other gases do not absorb, and they persist for many decades.","However, CO₂ is present in a vastly greater amount, so overall it makes the larger contribution to global warming."]},{"q":[["23.12",18]],"s":["Pure rain dissolves atmospheric carbon dioxide, forming the weak acid carbonic acid: CO₂ + H₂O ⇌ H₂CO₃ ⇌ H⁺ + HCO₃⁻, which gives a pH of about 5.6.","When SO₂ and NOₓ from burning fuels dissolve and form strong acids (H₂SO₄, H₂SO₃, HNO₃), the pH falls below 5.6 and the rain is called acid rain."]},{"q":[["23.12",19]],"s":["A three-way catalytic converter (Pt, Pd and Rh on a ceramic honeycomb) removes three pollutants from vehicle exhaust at once:","carbon monoxide → CO₂ (2CO + O₂ → 2CO₂); unburnt hydrocarbons → CO₂ + H₂O; nitrogen oxides → N₂ (2NO + 2CO → N₂ + 2CO₂)."]}],"longQuestions":[{"q":[["23.12",21],["23.12",22]],"s":["(i) Green chemistry is the design of chemical products and processes that reduce or eliminate the use and production of hazardous substances. Instead of treating pollution after it is made, it prevents pollution at its source — hence it is a new route to environmental protection.","Its twelve principles include: prevention of waste, atom economy, less hazardous syntheses, designing safer chemicals, safer solvents and auxiliaries (water, supercritical CO₂), energy efficiency, renewable feedstocks, reducing unnecessary steps, catalysis, design for degradation, real-time monitoring and inherently safer chemistry. Examples: the greener synthesis of ibuprofen with higher atom economy, water-based paints, biodegradable plastics, enzyme catalysts, and CO₂ instead of CFCs as blowing agents.","(ii) Greenhouse effect: short-wave radiation from the Sun passes through the atmosphere and warms the Earth's surface, which then emits long-wave infrared radiation. Greenhouse gases (CO₂, CH₄, N₂O, H₂O, CFCs) absorb this infrared and re-radiate much of it back to the surface, keeping the Earth warm (average ≈ 15 °C instead of about −18 °C) — like the glass of a greenhouse.","Global warming: burning fossil fuels, deforestation, agriculture and industry are increasing these gases, enhancing the greenhouse effect and raising the average global temperature. Consequences: melting glaciers and polar ice, rising sea levels and coastal flooding, more extreme weather (heatwaves, droughts, floods), changes in rainfall and crop yields, and loss of biodiversity."]},{"q":[["23.12",23],["23.12",24]],"s":["(i) The atmosphere is the layer of gases surrounding the Earth, held by gravity: about 78% N₂, 21% O₂, 0.9% Ar, 0.04% CO₂, plus water vapour and traces of other gases. It supplies oxygen, protects from UV and meteors, and regulates temperature.","Layers (by temperature change): Troposphere (0–11/12 km) — temperature falls from about 15 °C to −56 °C; contains most of the air and water vapour; weather occurs here. Stratosphere (12–50 km) — temperature rises from −56 °C to about −2 °C because the ozone layer absorbs UV. Mesosphere (50–85 km) — temperature falls to about −92 °C, the coldest layer; meteors burn up here. Thermosphere (85–500 km) — temperature rises to about 1200 °C as gases absorb high-energy radiation; contains the ionosphere and aurorae. Exosphere — the outermost layer, merging with space.","(ii) Air pollution is the presence in the air of substances (gases, particles) in amounts that are harmful to living things or materials. Main pollutants: CO, SO₂, NOₓ, hydrocarbons, particulate matter, O₃, lead and smoke — from vehicles, industry, power plants, burning of wastes and fuels.","Effects: respiratory diseases (asthma, bronchitis, lung cancer); CO poisoning (it forms carboxyhaemoglobin and reduces oxygen transport); eye and throat irritation; acid rain; smog; depletion of the ozone layer; global warming; damage to crops, forests, buildings and metals; and reduced visibility."]},{"q":[["23.12",25],["23.12",26]],"s":["(i) The ozone layer (in the stratosphere, about 15–35 km up) absorbs most of the Sun's harmful ultraviolet radiation (UV-B and UV-C, 200–315 nm). O₃ absorbs UV and splits: O₃ + hν → O₂ + O; the atoms re-form ozone: O + O₂ → O₃. In this cycle UV energy is converted into heat, warming the stratosphere and shielding life on Earth.","(ii) Without the ozone layer, intense UV radiation would reach the surface. It would cause sunburn, skin cancer and cataracts (eye damage); weaken the immune system; damage DNA and cause mutations; harm plants and reduce crop yields; kill phytoplankton, disturbing marine food chains; and degrade plastics, paints and other materials. Life on land as we know it could not survive."]},{"q":[["23.12",27]],"s":["Water pollution is any physical, chemical or biological change in the quality of water (rivers, lakes, seas, groundwater) that makes it harmful to humans, animals and plants or unfit for use.","Domestic sewage: organic matter, disease-causing micro-organisms (cholera, typhoid), detergents and phosphates — raising BOD and lowering dissolved oxygen.","Industrial effluents: heavy metals (Pb, Hg, Cd, Cr), acids, alkalis, dyes, oils, cyanides and other toxic chemicals from tanneries, textile mills, refineries and factories.","Agricultural run-off: fertilisers (nitrates, phosphates) causing eutrophication (algal blooms and oxygen depletion) and pesticides that accumulate in food chains.","Other sources: oil spills from tankers and pipelines; thermal pollution (hot water from power plants lowers DO); solid waste and plastics; radioactive wastes; mining and soil erosion (silt). Sources may be point (pipes, outlets) or non-point (run-off)."]},{"q":[["23.12",28]],"s":["(a) Acid rain: SO₂ and NOₓ from burning coal, oil and vehicle fuel are oxidised in the air and dissolve in rain: 2SO₂ + O₂ → 2SO₃; SO₃ + H₂O → H₂SO₄; 4NO₂ + O₂ + 2H₂O → 4HNO₃. Rain with pH below 5.6 corrodes buildings, statues and metals; acidifies lakes and kills fish; leaches nutrients and toxic aluminium from soil, damaging forests and crops; and harms human health. Control: low-sulphur fuels, flue-gas desulphurisation, catalytic converters, cleaner energy.","(b) Smog: Classical (London) smog forms in cold, damp weather from smoke, soot, SO₂ and fog; it is reducing and causes bronchitis and breathing problems. Photochemical (Los Angeles) smog forms in warm, sunny weather from NOₓ and hydrocarbons from vehicle exhaust: NO₂ + hν → NO + O; O + O₂ → O₃; O₃ and hydrocarbons give PAN and aldehydes. It is oxidising, appears as a brown haze, irritates eyes and lungs, and damages plants and rubber.","(c) Water treatment (drinking water): screening to remove large objects; sedimentation; coagulation/flocculation with alum to settle fine particles; filtration through sand and gravel beds; disinfection by chlorination (or ozone/UV) to kill germs; sometimes softening and fluoridation. Sewage treatment: primary (physical settling), secondary (biological — activated sludge or trickling filters decompose organic matter), tertiary (chemical removal of nitrates, phosphates and remaining pollutants).","(d) Chemistry of the stratosphere: ozone is formed when UV (λ < 242 nm) splits oxygen: O₂ → 2O; O + O₂ + M → O₃ + M. It is decomposed by UV: O₃ → O₂ + O, and O + O₃ → 2O₂ (Chapman cycle), keeping a steady concentration. CFCs disturb this balance: CF₂Cl₂ + hν → CF₂Cl• + Cl•; Cl• + O₃ → ClO• + O₂; ClO• + O → Cl• + O₂ — the chlorine atom is regenerated, so one atom destroys thousands of ozone molecules. NO from high-flying aircraft acts similarly, and polar stratospheric clouds over Antarctica speed up these reactions, producing the 'ozone hole'."]}],"activities":[{"q":[["23.12",30],["23.12",31]],"s":["The cotton plug holds the sand in place, and the layer of sand acts as a filter: the spaces between the sand grains are smaller than the suspended mud and clay particles, so these particles are trapped while water passes through.","The filtered water collected in the lower part looks clear and transparent.","Note: this removes only suspended (insoluble) impurities. Dissolved salts and germs (bacteria, viruses) pass through, so the water is not yet safe to drink — it must be boiled or chlorinated. Adding layers of gravel and activated charcoal improves the filter (charcoal also adsorbs some colour and odour)."]}]}},"24":{"items":{"mcqs":[{"q":[["24.12",2],["24.12",3]],"s":["Quantitative analysis measures how much of a substance is present.","Titration measures an amount (volume/concentration); salt analysis, the flame test and the bromine-water test are qualitative (they only identify)."],"inline":1,"c":1},{"q":[["24.12",4],["24.12",5]],"s":["C₂H₆O fits ethanol CH₃CH₂OH and dimethyl ether CH₃OCH₃.","Methanol is CH₄O and diethyl ether C₄H₁₀O. So (i) and (iii)."],"inline":1,"c":2},{"q":[["24.12",6],["24.12",7]],"s":["Each functional group (O–H, C=O, N–H, C≡N…) absorbs infrared radiation at a characteristic wavenumber.","IR spectroscopy is mainly used to identify functional groups."],"inline":1,"c":0},{"q":[["24.12",8],["24.12",9]],"s":["The fingerprint region (about 1500–625 cm⁻¹) contains a complex pattern of bending and skeletal vibrations that is unique to each compound.","Two different compounds always differ there, even if their functional-group regions look alike."],"inline":1,"c":0},{"q":[["24.12",10],["24.12",11]],"s":["NMR shows the number and kinds of hydrogen (or carbon) environments, their relative numbers and their neighbours.","It gives the most detailed information about the structure (connectivity) of an organic compound."],"inline":1,"c":1},{"q":[["24.12",12],["24.12",13],["24.12",14]],"s":["Reading the spectrum: the peaks are at m/z = 12, 16, 28 and 44, with the base (tallest) peak at 44.","m/z 44 is the molecular ion CO₂⁺; 28 is CO⁺, 16 is O⁺ and 12 is C⁺ — fragments of carbon dioxide.","N₂ would give its molecular ion at 28; C₃H₈ (M = 44) would also give many hydrocarbon fragments at 15, 29, 43; CH₄ + N₂ would give peaks at 16 and 28 only. So the compound is CO₂."],"d":"chem12-p193-mcq6-spectrum","inline":1,"c":0},{"q":[["24.12",15],["24.12",16]],"s":["Ultraviolet radiation lies between X-rays and visible light: about 10–400 nm (visible light is 400–800 nm)."],"inline":1,"c":3},{"q":[["24.12",17],["24.12",18]],"s":["Methane, ethane and cyclobutane each contain only one kind of proton, so each gives a single peak.","Butane CH₃CH₂CH₂CH₃ has two kinds (CH₃ and CH₂), giving more than one peak."],"inline":1,"c":2},{"q":[["24.12",19],["24.12",20]],"s":["1,1-Dichloroethane is CH₃–CHCl₂.","It has two kinds of protons (CH₃ and CHCl₂), so two signals (a doublet and a quartet)."],"inline":1,"c":0},{"q":[["24.12",21],["24.12",22]],"s":["Butanoic acid CH₃–CH₂–CH₂–COOH has protons in four different environments: CH₃, the middle CH₂, the CH₂ next to C=O, and COOH.","So there are 4 types of protons."],"inline":1,"c":3},{"q":[["24.12",23],["24.12",24]],"s":["In combustion analysis the water formed is absorbed in a tube of magnesium perchlorate, Mg(ClO₄)₂ (CO₂ is absorbed afterwards by NaOH)."],"inline":1,"c":0},{"q":[["24.12",25],["24.12",26]],"s":["Modern instrumental methods are more accurate and sensitive, need only tiny samples and are much faster.","All of the above."],"inline":1,"c":3},{"q":[["24.12",27],["24.12",28]],"s":["In-plane bending vibrations are scissoring and rocking; wagging and twisting are out-of-plane.","Scissoring is the in-plane bending vibration."],"inline":1,"c":1},{"q":[["24.12",29],["24.12",30]],"s":["A π → π* transition needs π electrons (a double bond).","Ethene has a C=C bond; ethane, ethyl alcohol and methyl chloride have only σ bonds (and lone pairs)."],"inline":1,"c":1},{"q":[["24.12",31],["24.12",32]],"s":["A nucleus is NMR-active only if it has a nuclear spin (an odd number of protons or neutrons, e.g. ¹H, ¹³C, ¹⁵N, ³¹P).","¹⁶O has 8 protons and 8 neutrons, so its spin is zero and it is NMR-inactive."],"n":"The first choice is printed as ³¹C; it should be ¹³C (an NMR-active nucleus).","inline":1,"c":3}],"shortQuestions":[{"q":[["24.12",34]],"s":["Stretching vibration: the atoms move along the bond axis so the bond length increases and decreases periodically; it may be symmetric or asymmetric.","Bending vibration: the bond angle changes while bond lengths stay the same — scissoring and rocking (in-plane), wagging and twisting (out-of-plane). Stretching needs more energy, so it absorbs at higher wavenumbers than bending."]},{"q":[["24.12",35]],"s":["Transmittance 100% means that all the incident radiation passes through the sample at that wavelength — nothing is absorbed.","So the compound has no bond or group that absorbs at that frequency (it is transparent there). If the whole spectrum shows 100% transmittance, the compound does not absorb in that region at all."]},{"q":[["24.12",36]],"s":["λmax is the wavelength at which a substance shows its maximum absorbance in its absorption (e.g. UV-visible) spectrum.","It is characteristic of the chromophore (absorbing group) and helps to identify the compound; measurements for concentration are made at λmax because sensitivity is greatest there (e.g. β-carotene, KMnO₄ at 525 nm)."]},{"q":[["24.12",37]],"s":["Beer–Lambert law: the absorbance of a solution is directly proportional to the concentration of the absorbing substance and to the path length of light through it: A = log(I₀/I) = εbc.","Here I₀ is the incident intensity, I the transmitted intensity, ε the molar absorptivity (a constant for the substance at that wavelength), b the path length (cm) and c the molar concentration. Measuring A at λmax therefore gives the concentration (using a calibration graph)."]},{"q":[["24.12",38]],"s":["Tetramethylsilane, Si(CH₃)₄, has twelve equivalent protons, so it gives one sharp, strong signal.","Silicon is less electronegative than carbon, so these protons are highly shielded and absorb upfield of almost all organic protons; the TMS signal is taken as δ = 0.","TMS is also chemically inert, non-polar, soluble in most organic solvents and volatile (b.p. 27 °C), so it is easily removed after the measurement."]},{"q":[["24.12",39]],"s":["In the ionisation chamber the vaporised sample is bombarded by a beam of high-energy electrons (about 70 eV). These knock electrons out of the molecules, forming positive molecular ions (M⁺) and fragment ions: M + e⁻ → M⁺ + 2e⁻.","Only charged particles can be accelerated by electric fields and deflected by magnetic fields, so ionisation is essential for separating the particles according to m/z."]},{"q":[["24.12",40]],"s":["Magnesium perchlorate (anhydrone) is a very strong, efficient drying agent that absorbs water vapour completely and quickly.","It does not absorb CO₂, so in combustion analysis the water is collected and weighed first, and CO₂ is absorbed separately afterwards (in NaOH); this allows hydrogen and carbon to be determined separately."]},{"q":[["24.12",41]],"s":["Modern (instrumental) methods are much faster and can be automated.","They need only very small amounts of sample (micrograms or less), are more sensitive and accurate, are often non-destructive, and give structural information (functional groups, connectivity, molecular mass) that classical gravimetric or volumetric methods cannot."]},{"q":[["24.13",0]],"s":["In the mass spectrum of an element each peak corresponds to one isotope: the number of peaks gives the number of isotopes, the m/z value gives each isotope's mass, and the peak height gives its relative abundance.","Example — chlorine: peaks at m/z 35 and 37 with heights in the ratio 3 : 1 (75% and 25%). So chlorine has two isotopes, ³⁵Cl and ³⁷Cl, and its average atomic mass = (35 × 75 + 37 × 25)/100 = 35.5."]},{"q":[["24.13",1]],"s":["Nuclei with spin, such as ¹H, behave like tiny magnets. In a strong external magnetic field they line up either with the field (lower energy, α-spin) or against it (higher energy, β-spin).","When radio-frequency radiation whose energy equals the energy gap (ΔE = hν) is supplied, the nucleus absorbs it and 'flips' from the α to the β state. This absorption (resonance) is detected as an NMR signal."]}],"longQuestions":[{"q":[["24.13",9],["24.13",10]],"s":["(a) Mass spectroscopy is a technique in which molecules are converted into gaseous ions that are separated according to their mass-to-charge ratio (m/z), giving atomic and molecular masses and structural information.","Construction and working: (i) inlet system — the sample is vaporised; (ii) ionisation chamber — the vapour is bombarded with high-energy electrons, forming positive molecular and fragment ions; (iii) accelerating plates — an electric field accelerates the ions into a narrow beam; (iv) analyser — a magnetic field deflects the ions into circular paths, r = mv/(qB), so ions of different m/z follow different paths; varying B or V brings each kind of ion in turn onto the detector; (v) detector — the ion current is amplified and recorded as a mass spectrum (relative abundance against m/z).","(b) Element: each peak is an isotope; the m/z values give isotopic masses and the heights their abundances, so relative atomic mass = Σ(isotopic mass × % abundance)/100 (e.g. neon: ²⁰Ne 90.5%, ²¹Ne 0.3%, ²²Ne 9.2% → 20.18).","Compound: the molecular-ion peak M⁺ (the peak at the highest m/z, apart from small isotope peaks) gives the molecular mass; the fragment peaks (and the base peak, the tallest) give clues to the structure, e.g. CH₃⁺ at 15, C₂H₅⁺ at 29."]},{"q":[["24.13",11],["24.13",12],["24.13",13]],"s":["(a) Atomic emission spectroscopy: atoms are excited (in a flame, arc or plasma); as they return to lower levels they emit light of characteristic wavelengths; the intensity of the emitted lines is measured (bright lines on a dark background). Atomic absorption spectroscopy: ground-state atoms in a flame absorb light of their characteristic wavelengths from an external source; the decrease in intensity (absorbance) is measured. Emission needs excited atoms; absorption uses the far more numerous ground-state atoms and is usually more sensitive.","(b) Flame photometer: the sample solution is sprayed (nebulised) into a flame; the atoms (Na, K, Li, Ca) are excited and emit their characteristic light; a filter isolates the wavelength (Na 589 nm, K 766 nm); a photocell measures the intensity, which is proportional to concentration. Atomic absorption spectrometer: a hollow-cathode lamp made of the element emits its characteristic lines, which pass through a flame (or graphite furnace) containing the atomised sample; the atoms absorb part of this light; a monochromator selects the line and a detector measures the absorbance.","(c) Qualitative analysis: the wavelengths of the emission or absorption lines are characteristic of each element (its 'fingerprint'), so they identify which elements are present. Quantitative analysis: emission intensity or absorbance is proportional to concentration (Beer–Lambert law); a calibration graph made with standard solutions gives the concentration of the unknown. Uses: Na and K in blood serum, lead and mercury in water, trace metals in soil, food and alloys."]},{"q":[["24.13",14],["24.13",15],["24.13",16]],"s":["(a) Proton NMR (¹H NMR) spectroscopy is the study of the absorption of radio-frequency radiation by hydrogen nuclei placed in a strong magnetic field. Because protons in different chemical environments absorb at slightly different frequencies, it reveals the kinds of hydrogen atoms in a molecule.","(b) Electrons around a proton circulate in the applied field and set up a small opposing field, so the nucleus feels a slightly smaller field — it is shielded. More shielded protons absorb upfield (lower chemical shift, δ). Electronegative atoms or groups (O, N, halogens, C=O) withdraw electron density and deshield the proton, which then absorbs downfield (higher δ).","Chemical shift δ (ppm) = (ν_sample − ν_TMS)/ν_spectrometer × 10⁶, with TMS at δ = 0. Typical values: C–CH₃ ≈ 0.9; CH₃–C=O ≈ 2.1; CH₃–O ≈ 3.3; aromatic H ≈ 7–8; –CHO ≈ 9–10; –COOH ≈ 10–12.","(c) Number of signals = number of chemically different kinds of protons; the position (δ) of each signal shows its environment; the area under each signal (integration) gives the relative number of protons of that kind; splitting (n + 1 rule) shows the number of neighbouring protons. Example: ethanol CH₃CH₂OH gives three signals (CH₃ triplet, CH₂ quartet, OH singlet) with areas 3 : 2 : 1."]},{"q":[["24.13",17],["24.13",18]],"s":["(a) UV-visible spectroscopy is based on the absorption of ultraviolet (200–400 nm) or visible (400–800 nm) radiation by molecules, which promotes electrons from lower-energy (bonding or non-bonding) orbitals to higher-energy (antibonding) orbitals. A spectrophotometer (deuterium/tungsten lamp, monochromator, quartz cell, detector) records absorbance against wavelength; λmax and the molar absorptivity are characteristic of the chromophore (C=C, C=O, conjugated systems, aromatic rings). Conjugation lowers the energy gap and shifts λmax to longer wavelengths. Absorbance obeys the Beer–Lambert law, so concentrations can be measured.","(b) Electronic transitions in organic molecules: σ → σ* — in saturated compounds (alkanes); needs very high energy (λ < 150 nm, far UV). n → σ* — in compounds with lone pairs on O, N, S or halogens (alcohols, amines, alkyl halides); about 150–250 nm.","π → π* — in compounds with double or triple bonds and aromatic rings (ethene ≈ 171 nm, buta-1,3-diene ≈ 217 nm); strong absorption that shifts to longer λ with conjugation. n → π* — in compounds with a lone pair on an atom that is part of a π bond (C=O of aldehydes and ketones, ≈ 280–300 nm); lowest energy and weak absorption.","Energy order: σ → σ* > n → σ* > π → π* > n → π*."]},{"q":[["24.13",19],["24.13",20],["24.13",21]],"s":["(a) Infrared (IR) spectroscopy is the study of the absorption of infrared radiation (about 4000–625 cm⁻¹) by molecules, which excites the vibrations of their bonds. Only vibrations that change the dipole moment absorb. The spectrum (% transmittance against wavenumber) shows which bonds and functional groups are present.","(b) Molecular vibrations: stretching — the bond length changes along the bond axis; symmetric (both bonds stretch together) or asymmetric (one stretches as the other contracts). Bending — the bond angle changes; in-plane scissoring and rocking, out-of-plane wagging and twisting. A non-linear molecule of N atoms has 3N − 6 fundamental vibrations (3N − 5 if linear); e.g. H₂O has 3 and CO₂ has 4.","(c) Functional-group region (4000–1500 cm⁻¹): absorptions here are characteristic of particular bonds — O–H (3200–3600, broad), N–H (3300–3500), C–H (2850–3100), C≡N (≈ 2250), C≡C (2100–2260), C=O (1650–1750, strong), C=C (1620–1680) — so it identifies the functional groups present.","Fingerprint region (1500–625 cm⁻¹): a complicated pattern of bending and skeletal (C–C, C–O, C–N) vibrations that is unique to each compound; comparing it with the spectrum of a known sample confirms the identity of the compound, just as a fingerprint identifies a person."]}],"numericals":[{"q":[["24.13",3]],"s":["Oxygen % = 100 − (32 + 4) = 64%.","Moles: C = 32/12 = 2.67; H = 4/1 = 4; O = 64/16 = 4. Divide by 2.67: C 1, H 1.5, O 1.5; multiply by 2: C₂H₃O₃.","Empirical-formula mass = 2(12) + 3(1) + 3(16) = 75.","n = 150/75 = 2, so the molecular formula is C₄H₆O₆ (tartaric acid)."],"a":"C₄H₆O₆"},{"q":[["24.13",4]],"s":["Moles: C = 27.3/12 = 2.275; O = 72.7/16 = 4.544.","Ratio C : O = 2.275 : 4.544 = 1 : 2.","Empirical formula = CO₂."],"a":"CO₂"},{"q":[["24.13",5]],"s":["Mass of C = 7.33 × 12/44 = 2.00 g → %C = 2.00/5 × 100 = 40.0%.","Mass of H = 3 × 2/18 = 0.333 g → %H = 0.333/5 × 100 = 6.67%.","Mass of O = 5 − 2.00 − 0.333 = 2.67 g → %O = 53.3%.","Moles: C = 40.0/12 = 3.33; H = 6.67/1 = 6.67; O = 53.3/16 = 3.33 → ratio 1 : 2 : 1. Empirical formula = CH₂O."],"a":"C 40.0%, H 6.67%, O 53.3%; empirical formula CH₂O"},{"q":[["24.13",6]],"s":["Moles: C = 88.17/12.01 = 7.34; H = 11.83/1.008 = 11.74.","Ratio C : H = 1 : 1.6 = 5 : 8, so the empirical formula is C₅H₈.","Empirical-formula mass = 5(12.01) + 8(1.008) = 68.11, equal to the molecular mass, so n = 1.","Molecular formula = C₅H₈."],"a":"Empirical and molecular formula C₅H₈"},{"q":[["24.13",7]],"s":["Mass of C = 3.94 × 12/44 = 1.075 g → moles C = 1.075/12 = 0.0896.","Mass of H = 1.61 × 2.016/18.02 = 0.180 g → moles H = 0.180/1.008 = 0.179. (Check: 1.075 + 0.180 = 1.255 ≈ 1.26 g, so there is no oxygen.)","Ratio C : H = 0.0896 : 0.179 = 1 : 2.","Empirical formula = CH₂."],"a":"CH₂"}],"activities":[{"q":[["24.13",23],["24.13",24]],"s":["C₃H₆O with only one proton NMR signal must have all six hydrogens equivalent: acetone (propanone), CH₃–CO–CH₃ — one singlet at δ ≈ 2.1.","Isomeric butyl bromides C₄H₉Br and their number of ¹H NMR signals:","n-Butyl bromide CH₃CH₂CH₂CH₂Br — 4 signals; sec-butyl bromide CH₃CHBrCH₂CH₃ — 4 signals; isobutyl bromide (CH₃)₂CHCH₂Br — 3 signals; tert-butyl bromide (CH₃)₃CBr — 1 signal."]}]}}});
